window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"pl-sprints":{src:"act:sprints",route:"#/atlas/honey/sprints",cta:"Open the Subject Sprints",title:"Act VIII · The Subject Sprints",body:"17 stops on this road, from “Medical Body Systems Vocabulary” to “Philosophical & Religious Vocabulary”."},"li-u97":{src:"concept:88:concept",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary",body:"Medical vocabulary follows a strict pattern: Greek or Latin body-part root + Greek suffix = a medical term. Once you know the six major body-system roots and the handful of suffixes, you can decode any medical word."},"lc-u97-0":{src:"concept:88:cards:0",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary · Cardio (Heart)",body:"Cardiovascular = heart + blood vessels. Myocardial (myo- = muscle) = relating to the heart muscle. Pericarditis = inflammation of the membrane around the heart. Electrocardiogram (EKG) = electro- + cardio- + -gram = 17 letters that all follow Greek spelling rules perfectly."},"lc-u97-1":{src:"concept:88:cards:1",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary · Neuro (Brain/Nerve)",body:"Neurological = relating to the nervous system. Neurotransmitter = chemical messenger between nerves. Encephalitis (encephalo- = brain) = brain inflammation. Meningitis (meninges = membranes around brain) = inflammation of brain membranes. Every -itis = inflammation; every neuro- = nerve."},"lc-u97-2":{src:"concept:88:cards:2",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary · Gastro (Stomach/Gut)",body:"Gastrointestinal = stomach + intestines. Gastroenterology = gastro- + entero- (intestine) + -logy = the study of the digestive system. Esophagus (oisophagos = food carrier) = the food tube. Peristalsis (peri- = around + stalsis = contraction) = the wave motion of the gut."},"lc-u97-3":{src:"concept:88:cards:3",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary · Pulmo (Lung) & Hema (Blood)",body:"Pulmonary (pulmo = lung) = relating to the lungs. Pneumonia (pneumon = lung) = lung inflammation. Hematopoiesis (hemato- = blood + poiesis = making) = making blood cells in the bone marrow. Hemoglobin = the oxygen-carrying blood protein. ⚠️ Pneumonia has a silent p — P-N-E-U-M-O-N-I-A."},"lc-u97-4":{src:"concept:88:cards:4",route:"#/stop/u97",cta:"Open this stop",title:"Medical Body Systems Vocabulary · The Spell-It System",body:"Every medical term = [body part] + [what is happening]. Hepatitis (hepato- = liver + -itis) = liver inflammation. Nephrology (nephro- = kidney + -logy) = study of kidneys. Ophthalmoscopy (ophthalmos- + -scopy) = examination of the eye. Learn the part + the suffix = decode any medical word."},"uq-u97-0":{src:"unit:u97:qs:0",route:"#/stop/u97",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Medical Body Systems Vocabulary”?",opts:["Medical vocabulary follows a strict pattern: Greek or Latin body-part root + Greek suffix = a medical term.","Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of.","Latin inter- = between two or more things."],after:"From “Medical Body Systems Vocabulary”."}},"uq-u97-3":{src:"unit:u97:qs:3",route:"#/stop/u97",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ — your heart pumps through VASCUlar tubes; no extra A sneaks into VASCUL.” — which word is this hook about?",opts:["cardiovascular","myocardial","electrocardiogram","neurological"],after:"From “Medical Body Systems Vocabulary”."}},"wd-myocardial":{src:"concept:88:words:1:def",route:"#/word/myocardial",cta:"Open the word card",title:"myocardial",roman:"meye-uh-KAH-rdee-uhl",body:"of or relating to the myocardium",clip:1},"wx-myocardial":{src:"concept:88:words:1:ex",route:"#/word/myocardial",cta:"Open the word card",title:"In a sentence · myocardial",body:"The doctor explained that a myocardial infarction is the medical term for what most people call a heart attack.",clip:1},"wh-myocardial":{src:"concept:88:words:1:hook",route:"#/word/myocardial",cta:"Open the word card",title:"Remember it · myocardial",body:"A MYOCARDIAL event targets the heart muscle — end it with -IAL like 'trial of the heart.'"},"wd-neurological":{src:"concept:88:words:3:def",route:"#/word/neurological",cta:"Open the word card",title:"neurological",roman:"nuu-ruh-LAH-jih-kuhl",body:"of or relating to or used in or practicing neurology",clip:1},"wh-neurological":{src:"concept:88:words:3:hook",route:"#/word/neurological",cta:"Open the word card",title:"Remember it · neurological",body:"A NEUROn's LOGICal path through the brain makes it NEUROLOGICAl."},"wd-neurotransmitter":{src:"concept:88:words:4:def",route:"#/word/neurotransmitter",cta:"Open the word card",title:"neurotransmitter",roman:"nyoor-oh-TRANZ-mit-er",body:"a neurochemical that transmits nerve impulses across a synapse",clip:1},"wx-neurotransmitter":{src:"concept:88:words:4:ex",route:"#/word/neurotransmitter",cta:"Open the word card",title:"In a sentence · neurotransmitter",body:"Dopamine is a neurotransmitter that plays a key role in how we feel pleasure and stay motivated.",clip:1},"wh-neurotransmitter":{src:"concept:88:words:4:hook",route:"#/word/neurotransmitter",cta:"Open the word card",title:"Remember it · neurotransmitter",body:"NEURO + TRANSMITTER: a TRANSMITTER sends signals — a NEUROTRANSMITTER sends signals between nerve cells, spelled by joining both."},"wd-encephalitis":{src:"concept:88:words:5:def",route:"#/word/encephalitis",cta:"Open the word card",title:"encephalitis",roman:"eh-nseh-fuh-LEYE-tuhs",body:"inflammation of the brain usually caused by a virus; symptoms include headache and neck pain and drowsiness and nausea and fever (`phrenitis' is no longer in scientific use)",clip:1},"wx-encephalitis":{src:"concept:88:words:5:ex",route:"#/word/encephalitis",cta:"Open the word card",title:"In a sentence · encephalitis",body:"After contracting the mosquito-borne virus, the hiker was hospitalized with encephalitis, which caused severe headaches and confusion.",clip:1},"wh-encephalitis":{src:"concept:88:words:5:hook",route:"#/word/encephalitis",cta:"Open the word card",title:"Remember it · encephalitis",body:"Think 'en-CEPH-al' — the cephalopod uses its brain, and this is brain inflammation"},"wo-encephalitis":{src:"lore:encephalitis:0",route:"#/word/encephalitis",cta:"Open the word card",title:"Where it comes from · encephalitis",body:"Greek enkephalos = brain + -itis = inflammation"},"wd-meningitis":{src:"concept:88:words:6:def",route:"#/word/meningitis",cta:"Open the word card",title:"meningitis",roman:"meh-nuh-NJEYE-tuhs",body:"infectious disease characterized by inflammation of the meninges (the tissues that surround the brain or spinal cord) usually caused by a bacterial infection; symptoms include headache and stiff neck and fever and nausea",clip:1},"wx-meningitis":{src:"concept:88:words:6:ex",route:"#/word/meningitis",cta:"Open the word card",title:"In a sentence · meningitis",body:"The school nurse urged all parents to vaccinate their children against meningitis before the new semester began.",clip:1},"wh-meningitis":{src:"concept:88:words:6:hook",route:"#/word/meningitis",cta:"Open the word card",title:"Remember it · meningitis",body:"MEN-IN-GI-TIS: the inflammation that gets INTO the brain's membrane IS serious."},"wo-meningitis":{src:"lore:meningitis:0",route:"#/word/meningitis",cta:"Open the word card",title:"Where it comes from · meningitis",body:"Greek meninx = membrane + itis = inflammation"},"wd-gastrointestinal":{src:"concept:88:words:7:def",route:"#/word/gastrointestinal",cta:"Open the word card",title:"gastrointestinal",roman:"ga-stroh-ih-NTEH-stuh-nuhl",body:"of or relating to the stomach and intestines",clip:1},"wx-gastrointestinal":{src:"concept:88:words:7:ex",route:"#/word/gastrointestinal",cta:"Open the word card",title:"In a sentence · gastrointestinal",body:"a gastrointestinal disorder",clip:1},"wh-gastrointestinal":{src:"concept:88:words:7:hook",route:"#/word/gastrointestinal",cta:"Open the word card",title:"Remember it · gastrointestinal",body:"GASTRO+INTESTINAL: your GASTRO tract leads INTO your INTESTINES — the word maps the journey."},"wo-gastrointestinal":{src:"lore:gastrointestinal:0",route:"#/word/gastrointestinal",cta:"Open the word card",title:"Where it comes from · gastrointestinal",body:"Greek gaster = stomach + Latin intestinum = intestine"},"wd-esophagus":{src:"concept:88:words:9:def",route:"#/word/esophagus",cta:"Open the word card",title:"esophagus",roman:"ih-SAH-fuh-guhs",body:"the passage between the pharynx and the stomach",clip:1},"wx-esophagus":{src:"concept:88:words:9:ex",route:"#/word/esophagus",cta:"Open the word card",title:"In a sentence · esophagus",body:"When you swallow food, it travels down the esophagus and into your stomach within just a few seconds.",clip:1},"wh-esophagus":{src:"concept:88:words:9:hook",route:"#/word/esophagus",cta:"Open the word card",title:"Remember it · esophagus",body:"Your ESOPHAGUS carries food—ESO(inside)+PHAG(eat)+US; it ends in -US not -OUS, because one tube, not an adjective."},"wo-esophagus":{src:"lore:esophagus:0",route:"#/word/esophagus",cta:"Open the word card",title:"Where it comes from · esophagus",body:"Greek oisophagos = gullet (oiso=carry + phagein=eat)"},"wd-pulmonary":{src:"concept:88:words:11:def",route:"#/word/pulmonary",cta:"Open the word card",title:"pulmonary",roman:"PUU-lmuh-neh-ree",body:"relating to or affecting the lungs",clip:1},"wx-pulmonary":{src:"concept:88:words:11:ex",route:"#/word/pulmonary",cta:"Open the word card",title:"In a sentence · pulmonary",body:"After the doctor reviewed the X-rays, she explained that the pulmonary infection had spread to both lungs and would require a full course of strong antibiotics to treat.",clip:1},"wh-pulmonary":{src:"concept:88:words:11:hook",route:"#/word/pulmonary",cta:"Open the word card",title:"Remember it · pulmonary",body:"PULMOnary: your PULMOn (lung) needs air — don't leave out the 'o' before '-ary'."},"wo-pulmonary":{src:"lore:pulmonary:0",route:"#/word/pulmonary",cta:"Open the word card",title:"Where it comes from · pulmonary",body:"Latin pulmo = lung"},"wd-pneumonia":{src:"concept:88:words:12:def",route:"#/word/pneumonia",cta:"Open the word card",title:"pneumonia",roman:"n-oo-m-OH-n-y-uh",body:"is inflammation of the lungs with congestion",clip:1},"wx-pneumonia":{src:"concept:88:words:12:ex",route:"#/word/pneumonia",cta:"Open the word card",title:"In a sentence · pneumonia",body:"After being caught in the freezing rain for hours, she developed pneumonia and had to be hospitalized.",clip:1},"wh-pneumonia":{src:"concept:88:words:12:hook",route:"#/word/pneumonia",cta:"Open the word card",title:"Remember it · pneumonia",body:"PNEUMonia attacks the lungs — the silent P-N-E-U-M is the hardest part; picture a PNEUMATIC pump filling diseased lungs."},"wo-pneumonia":{src:"lore:pneumonia:0",route:"#/word/pneumonia",cta:"Open the word card",title:"Where it comes from · pneumonia",body:"Greek pneumon = lung"},"wd-hematopoiesis":{src:"concept:88:words:13:def",route:"#/word/hematopoiesis",cta:"Open the word card",title:"hematopoiesis",roman:"hee-mat-oh-poy-EE-sis",body:"the formation of blood cells in the living body (especially in the bone marrow)",clip:1},"wx-hematopoiesis":{src:"concept:88:words:13:ex",route:"#/word/hematopoiesis",cta:"Open the word card",title:"In a sentence · hematopoiesis",body:"Doctors studied the patient's hematopoiesis to understand why his red blood cell count was so low.",clip:1},"wh-hematopoiesis":{src:"concept:88:words:13:hook",route:"#/word/hematopoiesis",cta:"Open the word card",title:"Remember it · hematopoiesis",body:"HEMATO (blood) + POIESIS (making) — your bones MAKE blood through hematopoiESIS."},"wd-hemoglobin":{src:"concept:88:words:14:def",route:"#/word/hemoglobin",cta:"Open the word card",title:"hemoglobin",roman:"hee-muh-GLOH-buhn",body:"a hemoprotein composed of globin and heme that gives red blood cells their characteristic color; function primarily to transport oxygen from the lungs to the body tissues",clip:1},"wx-hemoglobin":{src:"concept:88:words:14:ex",route:"#/word/hemoglobin",cta:"Open the word card",title:"In a sentence · hemoglobin",body:"fish have simpler hemoglobin than mammals",clip:1},"wh-hemoglobin":{src:"concept:88:words:14:hook",route:"#/word/hemoglobin",cta:"Open the word card",title:"Remember it · hemoglobin",body:"HEMOGLOBin: a GLOBe of iron in your blood that grabs oxygen — end it with -IN like a protein."},"wo-hemoglobin":{src:"lore:hemoglobin:0",route:"#/word/hemoglobin",cta:"Open the word card",title:"Where it comes from · hemoglobin",body:"Greek haima = blood + Latin globus = ball + -in = protein"},"wd-hepatitis":{src:"concept:88:words:15:def",route:"#/word/hepatitis",cta:"Open the word card",title:"hepatitis",roman:"heh-puh-TEYE-tuhs",body:"inflammation of the liver caused by a virus or a toxin",clip:1},"wx-hepatitis":{src:"concept:88:words:15:ex",route:"#/word/hepatitis",cta:"Open the word card",title:"In a sentence · hepatitis",body:"The doctor explained that hepatitis can damage the liver if it is not treated quickly.",clip:1},"wh-hepatitis":{src:"concept:88:words:15:hook",route:"#/word/hepatitis",cta:"Open the word card",title:"Remember it · hepatitis",body:"HepaTITIS ends in -ITIS like all inflammations — the liver is on FIRE, and ITIS is the alarm."},"wo-hepatitis":{src:"lore:hepatitis:0",route:"#/word/hepatitis",cta:"Open the word card",title:"Where it comes from · hepatitis",body:"Greek hepar = liver + itis = inflammation"},"li-u98":{src:"concept:89:concept",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary",body:"Science vocabulary is systematically built from Greek and Latin roots. Every term follows the pattern: process + modifier + suffix. Once you know the roots, science words spell themselves."},"lc-u98-0":{src:"concept:89:cards:0",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary · Biology Words",body:"Photosynthesis = light + together + placing = plants converting light to food. Metamorphosis = change of form. Symbiosis = living together mutually. Mitosis (mitos = thread) = cell division where chromosomes thread through. Meiosis (meioun = to lessen) = cell division that halves chromosomes."},"lc-u98-1":{src:"concept:89:cards:1",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary · Chemistry Words",body:"Catalysis (katalysis = dissolution) = chemical reaction facilitated by a catalyst. Electrolysis (electro- + lysis = breaking) = breaking chemical bonds with electricity. Stoichiometry (stoikheion = element + metry) = measuring chemical proportions. Exothermic = releases heat."},"lc-u98-2":{src:"concept:89:cards:2",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary · Physics Words",body:"Electromagnetic = electric + magnetic fields together. Thermodynamics = thermo- + dynamis (power) = science of heat and energy. Centrifugal (centri- + fuga = flight) = fleeing from center. Centripetal (centri- + petere = seek) = seeking the center."},"lc-u98-3":{src:"concept:89:cards:3",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary · Geology Words",body:"Sedimentary (sedimentum = settling) = rock formed from settled particles. Igneous (ignis = fire) = rock formed from volcanic fire. Metamorphic = rock changed in form by heat/pressure. Stratigraphic (stratum + graphos) = the written record of rock layers."},"lc-u98-4":{src:"concept:89:cards:4",route:"#/stop/u98",cta:"Open this stop",title:"Natural Science Vocabulary · Spelling Science Words",body:"The key: always ask which language. Greek words use ph, y as vowel, ch = /k/. Latin words use -tion, -al, -ous. Photosynthesis has five Greek elements all spelled predictably. Stoichiometry = S-T-O-I-C-H-I-O-M-E-T-R-Y — break it: stoikheion + -metry."},"uq-u98-0":{src:"unit:u98:qs:0",route:"#/stop/u98",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Natural Science Vocabulary”?",opts:["Science vocabulary is systematically built from Greek and Latin roots.","Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of.","Latin inter- = between two or more things."],after:"From “Natural Science Vocabulary”."}},"uq-u98-3":{src:"unit:u98:qs:3",route:"#/stop/u98",cta:"Open this stop",title:"Whose hook?",play:{q:"“PHOTO-SYN-THE-SIS: plants use PHOTO (light) to SYN-THE-SIZE food — end it with -SIS like 'crisis.'” — which word is this hook about?",opts:["photosynthesis","metamorphosis","symbiosis","mitosis"],after:"From “Natural Science Vocabulary”."}},"wd-mitosis":{src:"concept:89:words:3:def",route:"#/word/mitosis",cta:"Open the word card",title:"mitosis",roman:"my-TOH-sis",body:"cell division in which the nucleus divides into nuclei containing the same number of chromosomes",clip:1},"wx-mitosis":{src:"concept:89:words:3:ex",route:"#/word/mitosis",cta:"Open the word card",title:"In a sentence · mitosis",body:"During biology class, we watched a time-lapse video of mitosis showing one cell splitting perfectly into two identical daughter cells.",clip:1},"wh-mitosis":{src:"concept:89:words:3:hook",route:"#/word/mitosis",cta:"Open the word card",title:"Remember it · mitosis",body:"MITOSIS splits the cell — picture chromosomes as THREADS (mitos) being pulled apart: MI-TO-SIS."},"wd-meiosis":{src:"concept:89:words:4:def",route:"#/word/meiosis",cta:"Open the word card",title:"meiosis",roman:"meye-OH-suhs",body:"(genetics) cell division that produces reproductive cells in sexually reproducing organisms; the nucleus divides into four nuclei each containing half the chromosome number (leading to gametes in animals and spores in plants)",clip:1},"wx-meiosis":{src:"concept:89:words:4:ex",route:"#/word/meiosis",cta:"Open the word card",title:"In a sentence · meiosis",body:"During the unit on genetics, the class studied how meiosis produces four unique sex cells from a single parent cell, each with half the original chromosomes.",clip:1},"wh-meiosis":{src:"concept:89:words:4:hook",route:"#/word/meiosis",cta:"Open the word card",title:"Remember it · meiosis",body:"MEIOsis — MEIosis MEIns less; it REDUCES chromosome numbers in half like a sale cutting prices"},"wo-meiosis":{src:"lore:meiosis:0",route:"#/word/meiosis",cta:"Open the word card",title:"Where it comes from · meiosis",body:"Greek meiosis = lessening, from meioun = to make smaller, from meion = less"},"wd-catalysis":{src:"concept:89:words:6:def",route:"#/word/catalysis",cta:"Open the word card",title:"catalysis",roman:"kuh-TAL-uh-sis",body:"acceleration of a chemical reaction induced the presence of material that is chemically unchanged at the end of the reaction",clip:1},"wx-catalysis":{src:"concept:89:words:6:ex",route:"#/word/catalysis",cta:"Open the word card",title:"In a sentence · catalysis",body:"of the top 50 commodity chemicals, 30 are created directly by catalysis and another 6 are made from raw materials that are catalytically produced",clip:1},"wh-catalysis":{src:"concept:89:words:6:hook",route:"#/word/catalysis",cta:"Open the word card",title:"Remember it · catalysis",body:"CataLYSIS ends in '-lysis' like analysis — both involve breaking things DOWN systematically."},"wo-catalysis":{src:"lore:catalysis:0",route:"#/word/catalysis",cta:"Open the word card",title:"Where it comes from · catalysis",body:"Greek katalysis = dissolution, kata-(down)+lyein(to loosen)"},"wd-electrolysis":{src:"concept:89:words:7:def",route:"#/word/electrolysis",cta:"Open the word card",title:"electrolysis",roman:"ih-leh-KTRAH-luh-suhs",body:"(chemistry) a chemical decomposition reaction produced by passing an electric current through a solution containing ions",clip:1},"wx-electrolysis":{src:"concept:89:words:7:ex",route:"#/word/electrolysis",cta:"Open the word card",title:"In a sentence · electrolysis",body:"In chemistry class, we used electrolysis to split water into hydrogen and oxygen gases.",clip:1},"wh-electrolysis":{src:"concept:89:words:7:hook",route:"#/word/electrolysis",cta:"Open the word card",title:"Remember it · electrolysis",body:"ELECTROLYSIS ends in '-lysis' like ANALYSIS — both involve breaking something apart; electricity breaks down the solution."},"wo-electrolysis":{src:"lore:electrolysis:0",route:"#/word/electrolysis",cta:"Open the word card",title:"Where it comes from · electrolysis",body:"Greek elektron = amber + lysis = loosening, dissolving"},"wd-electromagnetic":{src:"concept:89:words:9:def",route:"#/word/electromagnetic",cta:"Open the word card",title:"electromagnetic",roman:"ih-leh-ktroh-ma-GNEH-tihk",body:"pertaining to or exhibiting magnetism produced by electric charge in motion",clip:1},"wx-electromagnetic":{src:"concept:89:words:9:ex",route:"#/word/electromagnetic",cta:"Open the word card",title:"In a sentence · electromagnetic",body:"electromagnetic energy",clip:1},"wh-electromagnetic":{src:"concept:89:words:9:hook",route:"#/word/electromagnetic",cta:"Open the word card",title:"Remember it · electromagnetic",body:"ELECTROMAGNETIC — the 'r' in 'electro' stays strong before 'magnetic'; electricity and magnetism are inseparable partners."},"wo-electromagnetic":{src:"lore:electromagnetic:0",route:"#/word/electromagnetic",cta:"Open the word card",title:"Where it comes from · electromagnetic",body:"Greek elektron = amber + magnetes = Magnesian stone"},"wd-thermodynamics":{src:"concept:89:words:10:def",route:"#/word/thermodynamics",cta:"Open the word card",title:"thermodynamics",roman:"thur-moh-deye-NA-mihks",body:"the branch of physics concerned with the conversion of different forms of energy",clip:1},"wx-thermodynamics":{src:"concept:89:words:10:ex",route:"#/word/thermodynamics",cta:"Open the word card",title:"In a sentence · thermodynamics",body:"Understanding thermodynamics helped the engineering students explain why a car engine produces so much waste heat.",clip:1},"wh-thermodynamics":{src:"concept:89:words:10:hook",route:"#/word/thermodynamics",cta:"Open the word card",title:"Remember it · thermodynamics",body:"THERMO-DYNAM-ICS: the science (-ICS) of heat-power — no K, just a clean C before S."},"wo-thermodynamics":{src:"lore:thermodynamics:0",route:"#/word/thermodynamics",cta:"Open the word card",title:"Where it comes from · thermodynamics",body:"Greek therme = heat + dynamis = power"},"wd-centrifugal":{src:"concept:89:words:11:def",route:"#/word/centrifugal",cta:"Open the word card",title:"centrifugal",roman:"SEH-ntrih-fyoo-guhl",body:"tending to move away from a center",clip:1},"wx-centrifugal":{src:"concept:89:words:11:ex",route:"#/word/centrifugal",cta:"Open the word card",title:"In a sentence · centrifugal",body:"When the washing machine spun at full speed, the centrifugal force pushed the wet clothes outward against the drum wall, squeezing out most of the water.",clip:1},"wh-centrifugal":{src:"concept:89:words:11:hook",route:"#/word/centrifugal",cta:"Open the word card",title:"Remember it · centrifugal",body:"CENTRIFUGAL force FLEES the center — fugere means 'to flee,' so it FUGes away."},"wo-centrifugal":{src:"lore:centrifugal:0",route:"#/word/centrifugal",cta:"Open the word card",title:"Where it comes from · centrifugal",body:"Latin centrum = center + fugere = to flee"},"wd-sedimentary":{src:"concept:89:words:13:def",route:"#/word/sedimentary",cta:"Open the word card",title:"sedimentary",roman:"seh-duh-MEH-nter-ee",body:"resembling or containing or formed by the accumulation of sediment",clip:1},"wx-sedimentary":{src:"concept:89:words:13:ex",route:"#/word/sedimentary",cta:"Open the word card",title:"In a sentence · sedimentary",body:"sedimentary deposits",clip:1},"wh-sedimentary":{src:"concept:89:words:13:hook",route:"#/word/sedimentary",cta:"Open the word card",title:"Remember it · sedimentary",body:"Sediment settles at the bottom — remember '-ary' like 'library' where things are stored layer by layer."},"wo-sedimentary":{src:"lore:sedimentary:0",route:"#/word/sedimentary",cta:"Open the word card",title:"Where it comes from · sedimentary",body:"Latin sedimentum = settling, from sedere = to sit"},"wd-tectonic":{src:"concept:89:words:16:def",route:"#/word/tectonic",cta:"Open the word card",title:"tectonic",roman:"teh-KTAH-nihk",body:"of or relating to the structure, movement, and deformation of the earth's crust",clip:1},"wx-tectonic":{src:"concept:89:words:16:ex",route:"#/word/tectonic",cta:"Open the word card",title:"In a sentence · tectonic",body:"The tectonic shift of the Pacific Plate occurs so slowly that humans cannot feel it, yet it reshapes continents over millions of years.",clip:1},"wh-tectonic":{src:"concept:89:words:16:hook",route:"#/word/tectonic",cta:"Open the word card",title:"Remember it · tectonic",body:"TECTONic — TECT the structure of the earth's TONE layers"},"wo-tectonic":{src:"lore:tectonic:0",route:"#/word/tectonic",cta:"Open the word card",title:"Where it comes from · tectonic",body:"Greek tektonikos = of a builder, from tekton = builder, carpenter"},"li-u99":{src:"concept:90:concept",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary",body:"Arts vocabulary draws from Italian (music), French (dance and visual arts), and Greek (theory). Knowing the language of origin immediately suggests the spelling pattern."},"lc-u99-0":{src:"concept:90:cards:0",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary · Italian Music Dynamics",body:"Already covered in C47 — the key spelling pattern here is the -issimo superlative (pianissimo, fortissimo) with double-s, and the -etto/-etta diminutive (allegretto). Crescendo = C-R-E-S-C-E-N-D-O (-sc- before e = /s/). Diminuendo = D-I-M-I-N-U-E-N-D-O (from diminuere = lessen)."},"lc-u99-1":{src:"concept:90:cards:1",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary · Dance Vocabulary (French)",body:"Arabesque (Arab + -esque) = in the Arabic style = a ballet position. Pirouette = a spinning turn. Plié (plier = to bend) = a bending movement. Jeté (jeter = to throw) = a leap. Pas de deux (pas = step + de + deux = two) = a dance for two."},"lc-u99-2":{src:"concept:90:cards:2",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary · Visual Arts Terms",body:"Chiaroscuro (Italian) = light and dark contrast in painting. Impasto (Italian: impastare = to knead) = thick paint texture. Sfumato (Italian: sfumare = evaporate) = soft, hazy outlines. Pointillism (point = dot) = painting with dots of pure color."},"lc-u99-3":{src:"concept:90:cards:3",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary · Music Theory Terms",body:"Syncopation (syn- + koptein = cut) = rhythmic emphasis on normally unaccented beats. Counterpoint (contra- + punctus = point) = independent melodic lines sounding together. Cadenza (Italian, from cadere = fall) = an elaborate solo passage near a concerto's end."},"lc-u99-4":{src:"concept:90:cards:4",route:"#/stop/u99",cta:"Open this stop",title:"Fine Arts & Music Vocabulary · Architecture Terms",body:"Colonnade (colonna = column) = a row of columns. Corinthian, Doric, Ionic = the three Greek orders of columns. Tympanum (tympanon = drum) = the triangular space above a doorway. Buttress (French bouter = to push) = a structure built against a wall."},"uq-u99-0":{src:"unit:u99:qs:0",route:"#/stop/u99",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Fine Arts & Music Vocabulary”?",opts:["Arts vocabulary draws from Italian (music), French (dance and visual arts), and Greek (theory).","Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of.","Latin inter- = between two or more things."],after:"From “Fine Arts & Music Vocabulary”."}},"uq-u99-3":{src:"unit:u99:qs:3",route:"#/stop/u99",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: thick paint like thick PASTE pressed onto canvas” — which word is this hook about?",opts:["impasto","chiaroscuro","sfumato","pointillism"],after:"From “Fine Arts & Music Vocabulary”."}},"wd-impasto":{src:"concept:90:words:1:def",route:"#/word/impasto",cta:"Open the word card",title:"impasto",roman:"im-PAH-stoh",body:"painting that applies the pigment thickly so that brush or palette knife marks are visible",clip:1},"wx-impasto":{src:"concept:90:words:1:ex",route:"#/word/impasto",cta:"Open the word card",title:"In a sentence · impasto",body:"Van Gogh's masterful use of impasto makes his paintings look almost three-dimensional, with swirling ridges of paint you want to reach out and touch.",clip:1},"wh-impasto":{src:"concept:90:words:1:hook",route:"#/word/impasto",cta:"Open the word card",title:"Remember it · impasto",body:"IMPASTo: thick paint like thick PASTE pressed onto canvas"},"wd-syncopation":{src:"concept:90:words:6:def",route:"#/word/syncopation",cta:"Open the word card",title:"syncopation",roman:"SIH-ngkuh-pay-shuhn",body:"(phonology) the loss of sounds from within a word (as in `fo'c'sle' for `forecastle')",clip:1},"wx-syncopation":{src:"concept:90:words:6:ex",route:"#/word/syncopation",cta:"Open the word card",title:"In a sentence · syncopation",body:"The jazz drummer's use of syncopation gave the music an exciting, unpredictable rhythm that made everyone want to dance.",clip:1},"wh-syncopation":{src:"concept:90:words:6:hook",route:"#/word/syncopation",cta:"Open the word card",title:"Remember it · syncopation",body:"SYNCOPation is a COP cutting syllables — the COP in synCOPation is always on duty."},"wo-syncopation":{src:"lore:syncopation:0",route:"#/word/syncopation",cta:"Open the word card",title:"Where it comes from · syncopation",body:"Greek synkoptein = to cut short"},"wd-counterpoint":{src:"concept:90:words:7:def",route:"#/word/counterpoint",cta:"Open the word card",title:"counterpoint",roman:"KOW-nter-poynt",body:"a musical form involving the simultaneous sound of two or more melodies",clip:1},"wx-counterpoint":{src:"concept:90:words:7:ex",route:"#/word/counterpoint",cta:"Open the word card",title:"In a sentence · counterpoint",body:"Bach wrote counterpoint in which two melodies weave around each other like braided ribbons.",clip:1},"wh-counterpoint":{src:"concept:90:words:7:hook",route:"#/word/counterpoint",cta:"Open the word card",title:"Remember it · counterpoint",body:"Counter-POINT makes a musical POINT — POINT is spelled normally, because two melodies both make their point clearly."},"wo-counterpoint":{src:"lore:counterpoint:0",route:"#/word/counterpoint",cta:"Open the word card",title:"Where it comes from · counterpoint",body:"French contrepoint = against note, from Latin punctus = point/note"},"wd-cadenza":{src:"concept:90:words:8:def",route:"#/word/cadenza",cta:"Open the word card",title:"cadenza",roman:"kah-DEN-zah",body:"a brilliant solo passage occurring near the end of a piece of music",clip:1},"wx-cadenza":{src:"concept:90:words:8:ex",route:"#/word/cadenza",cta:"Open the word card",title:"In a sentence · cadenza",body:"The violinist's cadenza left the audience breathless with its dizzying speed and breathtaking emotion.",clip:1},"wh-cadenza":{src:"concept:90:words:8:hook",route:"#/word/cadenza",cta:"Open the word card",title:"Remember it · cadenza",body:"A cadENZA is an Italian FRENZY of solo notes — remember the Z like the zing of a violin."},"wo-cadenza":{src:"lore:cadenza:0",route:"#/word/cadenza",cta:"Open the word card",title:"Where it comes from · cadenza",body:"Italian cadenza = cadence, falling"},"wd-colonnade":{src:"concept:90:words:10:def",route:"#/word/colonnade",cta:"Open the word card",title:"colonnade",roman:"k-ah-l-uh-n-AY-d",body:"a series of regularly spaced columns",clip:1},"wx-colonnade":{src:"concept:90:words:10:ex",route:"#/word/colonnade",cta:"Open the word card",title:"In a sentence · colonnade",body:"The tourists walked through the shaded colonnade of the ancient temple, marveling at each towering marble column.",clip:1},"wh-colonnade":{src:"concept:90:words:10:hook",route:"#/word/colonnade",cta:"Open the word card",title:"Remember it · colonnade",body:"A colonnade has double 'n'—picture two columns standing side by side, just like the double 'n'."},"wo-colonnade":{src:"lore:colonnade:0",route:"#/word/colonnade",cta:"Open the word card",title:"Where it comes from · colonnade",body:"Italian colonna = column, from Latin columna"},"wd-tympanum":{src:"concept:90:words:11:def",route:"#/word/tympanum",cta:"Open the word card",title:"tympanum",roman:"TIH-mpuh-nuhm",body:"the main cavity of the ear; between the eardrum and the inner ear",clip:1},"wx-tympanum":{src:"concept:90:words:11:ex",route:"#/word/tympanum",cta:"Open the word card",title:"In a sentence · tympanum",body:"The doctor explained that the infection had spread to the tympanum, affecting the patient's hearing.",clip:1},"wh-tympanum":{src:"concept:90:words:11:hook",route:"#/word/tympanum",cta:"Open the word card",title:"Remember it · tympanum",body:"TYMPANUM is the eardrum — TYM-PAN-UM, your ear is a pan that UM-plifies sound."},"wo-tympanum":{src:"lore:tympanum:0",route:"#/word/tympanum",cta:"Open the word card",title:"Where it comes from · tympanum",body:"Greek tympanon = drum"},"wd-buttress":{src:"concept:90:words:12:def",route:"#/word/buttress",cta:"Open the word card",title:"buttress",roman:"BUH-truhs",body:"a support usually of stone or brick; supports the wall of a building",clip:1},"wx-buttress":{src:"concept:90:words:12:ex",route:"#/word/buttress",cta:"Open the word card",title:"In a sentence · buttress",body:"The medieval cathedral's stone buttress stretched outward from the tall wall like a sturdy arm, preventing the massive structure from crumbling under the enormous weight of its own roof.",clip:1},"wh-buttress":{src:"concept:90:words:12:hook",route:"#/word/buttress",cta:"Open the word card",title:"Remember it · buttress",body:"A BUTTRESS has a double T because it takes TWO supports to hold a wall up—and an -ess ending like 'fortress.'"},"wd-fenestration":{src:"concept:90:words:13:def",route:"#/word/fenestration",cta:"Open the word card",title:"fenestration",roman:"fen-es-TRAY-shun",body:"the arrangement of windows in a building",clip:1},"wx-fenestration":{src:"concept:90:words:13:ex",route:"#/word/fenestration",cta:"Open the word card",title:"In a sentence · fenestration",body:"The judge admired the fenestration of the old courthouse, where arched windows flooded every courtroom with golden afternoon light.",clip:1},"wh-fenestration":{src:"concept:90:words:13:hook",route:"#/word/fenestration",cta:"Open the word card",title:"Remember it · fenestration",body:"FENESTRA + TION — Latin fenestra means window; the -TION ending makes it the arrangement of windows."},"wo-fenestration":{src:"lore:fenestration:0",route:"#/word/fenestration",cta:"Open the word card",title:"Where it comes from · fenestration",body:"Latin: fenestratio (Latin)"},"li-u100":{src:"concept:91:concept",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary",body:"Food vocabulary is international — French dominates professional cooking, Italian contributes pasta and cheese terms, Spanish adds chili and spice words, Japanese contributes specific techniques. The spelling signals follow language of origin."},"lc-u100-0":{src:"concept:91:cards:0",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary · French Cooking Terms (Professional)",body:"Julienne = vegetables cut in thin matchsticks. Brunoise = vegetables cut in tiny cubes. Mirepoix = diced onion, celery, carrot base (-oi- = /wah/ French pattern). Beurre blanc = beurre (butter) + blanc (white) = a white butter sauce."},"lc-u100-1":{src:"concept:91:cards:1",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary · French Pastry & Restaurant Terms",body:"Crème brûlée (brûler = burn) = burned cream. Amuse-bouche (amuser = to amuse + bouche = mouth) = a tiny appetizer. Mise en place = mise (put) + en (in) + place (place) = everything in its place before cooking. Soufflé (souffler = to blow) = a dish that puffs up."},"lc-u100-2":{src:"concept:91:cards:2",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary · Italian Food Terms",body:"Bruschetta = B-R-U-S-C-H-E-T-T-A (-sch- = /sk/ in Italian; -tt- double). Prosciutto = P-R-O-S-C-I-U-T-T-O (-sci- = /sh/ in Italian; -tt-). Ossobuco (osso = bone + buco = hole) = braised veal shanks. Risotto (riso = rice + -otto = slightly enlarged) = creamy rice dish."},"lc-u100-3":{src:"concept:91:cards:3",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary · Spice & Ingredient Words",body:"Saffron (Arabic za'faran) = saf- → S-A-F-F-R-O-N (double-f). Turmeric = T-U-R-M-E-R-I-C (not tumeric — the first r is often omitted in speech). Cardamom = C-A-R-D-A-M-O-M (not cardamon). Worcestershire = WOO-ster-sheer (the spelling is radically longer than the pronunciation)."},"lc-u100-4":{src:"concept:91:cards:4",route:"#/stop/u100",cta:"Open this stop",title:"Culinary Vocabulary · Japanese Food Terms",body:"Teriyaki (teri = gloss + yaki = grilled) = T-E-R-I-Y-A-K-I (the CV syllable pattern: no consonant clusters). Edamame (eda = branch + mame = bean) = E-D-A-M-A-M-E. Tempura = T-E-M-P-U-R-A (Portuguese origin, adopted into Japanese). Miso = M-I-S-O. Wasabi = W-A-S-A-B-I."},"uq-u100-0":{src:"unit:u100:qs:0",route:"#/stop/u100",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Culinary Vocabulary”?",opts:["Food vocabulary is international — French dominates professional cooking, Italian contributes pasta and cheese terms, Spanish adds chili and spice words, Japane","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Culinary Vocabulary”."}},"uq-u100-1":{src:"unit:u100:qs:1",route:"#/stop/u100",cta:"Open this stop",title:"Which belongs?",play:{q:"Which word belongs to this chapter's family?",opts:["julienne","distraught","thought","desiccate"],after:"From “Culinary Vocabulary”."}},"uq-u100-3":{src:"unit:u100:qs:3",route:"#/stop/u100",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: JULIEN the French chef cuts everything into thin strips” — which word is this hook about?",opts:["julienne","brunoise","mirepoix","roux"],after:"From “Culinary Vocabulary”."}},"wd-julienne":{src:"concept:91:words:0:def",route:"#/word/julienne",cta:"Open the word card",title:"julienne",roman:"joo-lee-EN",body:"a vegetable cut into thin strips (usually used as a garnish)",clip:1},"wx-julienne":{src:"concept:91:words:0:ex",route:"#/word/julienne",cta:"Open the word card",title:"In a sentence · julienne",body:"The chef julienned the carrots and zucchini into perfectly uniform strips before arranging them in a colorful fan across the plate.",clip:1},"wh-julienne":{src:"concept:91:words:0:hook",route:"#/word/julienne",cta:"Open the word card",title:"Remember it · julienne",body:"JULIENne: JULIEN the French chef cuts everything into thin strips"},"wo-julienne":{src:"lore:julienne:0",route:"#/word/julienne",cta:"Open the word card",title:"Where it comes from · julienne",body:"Named after the French given name Julien or Julie; origin of the culinary use is uncertain"},"wd-brunoise":{src:"concept:91:words:1:def",route:"#/word/brunoise",cta:"Open the word card",title:"brunoise",roman:"broo-NWAZ",body:"A culinary technique in which vegetables or other foods are cut into very small, uniform cubes approximately one to three millimeters on each side, used to create fine garnishes or flavor bases.",clip:1},"wx-brunoise":{src:"concept:91:words:1:ex",route:"#/word/brunoise",cta:"Open the word card",title:"In a sentence · brunoise",body:"The chef's brunoise of carrots and celery was so perfectly uniform it looked machine-cut.",clip:1},"wh-brunoise":{src:"concept:91:words:1:hook",route:"#/word/brunoise",cta:"Open the word card",title:"Remember it · brunoise",body:"BRUNOISE: think 'brew noise in tiny cubes'—say bru-NWAZ, a French tiny-dice cut."},"wd-roux":{src:"concept:91:words:3:def",route:"#/word/roux",cta:"Open the word card",title:"roux",roman:"ROO",body:"a mixture of fat and flour heated and used as a basis for sauces",clip:1},"wx-roux":{src:"concept:91:words:3:ex",route:"#/word/roux",cta:"Open the word card",title:"In a sentence · roux",body:"She whisked the roux carefully over low heat until it turned a deep golden brown before adding the broth.",clip:1},"wh-roux":{src:"concept:91:words:3:hook",route:"#/word/roux",cta:"Open the word card",title:"Remember it · roux",body:"A ROUX sounds like 'roo' but hides an X at the end — think of a kangaroo chef making a sauce, signing with an X."},"wo-roux":{src:"lore:roux:0",route:"#/word/roux",cta:"Open the word card",title:"Where it comes from · roux",body:"French beurre roux = browned butter"},"wd-saffron":{src:"concept:91:words:9:def",route:"#/word/saffron",cta:"Open the word card",title:"saffron",roman:"s-A-f-r-uh-n",body:"is a crocus having showy purple flowers",clip:1},"wx-saffron":{src:"concept:91:words:9:ex",route:"#/word/saffron",cta:"Open the word card",title:"In a sentence · saffron",body:"The chef added a pinch of saffron to the rice, turning it a beautiful golden yellow color.",clip:1},"wh-saffron":{src:"concept:91:words:9:hook",route:"#/word/saffron",cta:"Open the word card",title:"Remember it · saffron",body:"SAFFRON is double 'f', single 'r' — two 'f's for the two stigmas you need to make this expensive spice."},"wo-saffron":{src:"lore:saffron:0",route:"#/word/saffron",cta:"Open the word card",title:"Where it comes from · saffron",body:"Arabic za'faran = yellow spice"},"wd-turmeric":{src:"concept:91:words:10:def",route:"#/word/turmeric",cta:"Open the word card",title:"turmeric",roman:"TUR-muh-rihk",body:"widely cultivated tropical plant of India having yellow flowers and a large aromatic deep yellow rhizome; source of a condiment and a yellow dye",clip:1},"wx-turmeric":{src:"concept:91:words:10:ex",route:"#/word/turmeric",cta:"Open the word card",title:"In a sentence · turmeric",body:"My grandmother stirred a teaspoon of golden turmeric into the simmering soup, filling the kitchen with a warm, earthy fragrance.",clip:1},"wh-turmeric":{src:"concept:91:words:10:hook",route:"#/word/turmeric",cta:"Open the word card",title:"Remember it · turmeric",body:"Remember the hidden 'r': tur-MER-ic, not tu-MER-ic — there's an 'r' in the middle."},"wo-turmeric":{src:"lore:turmeric:0",route:"#/word/turmeric",cta:"Open the word card",title:"Where it comes from · turmeric",body:"Middle French terre merite = deserving earth, from Latin terra (earth)"},"wd-cardamom":{src:"concept:91:words:11:def",route:"#/word/cardamom",cta:"Open the word card",title:"cardamom",roman:"KAH-rduh-muhm",body:"rhizomatous herb of India having aromatic seeds used as seasoning",clip:1},"wx-cardamom":{src:"concept:91:words:11:ex",route:"#/word/cardamom",cta:"Open the word card",title:"In a sentence · cardamom",body:"The warm chai tea was fragrant with cardamom, cinnamon, and ginger, filling the whole kitchen with spice.",clip:1},"wh-cardamom":{src:"concept:91:words:11:hook",route:"#/word/cardamom",cta:"Open the word card",title:"Remember it · cardamom",body:"CardaMOM — your MOM puts cardaMOM in her chai; remember MOM at the end."},"wo-cardamom":{src:"lore:cardamom:0",route:"#/word/cardamom",cta:"Open the word card",title:"Where it comes from · cardamom",body:"Greek kardamomon = spice plant, from kardamon = cress + amomon = spice"},"wd-worcestershire":{src:"concept:91:words:12:def",route:"#/word/worcestershire",cta:"Open the word card",title:"worcestershire",roman:"WUU-ster-sher",body:"a savory sauce of vinegar and soy sauce and spices",clip:1},"wx-worcestershire":{src:"concept:91:words:12:ex",route:"#/word/worcestershire",cta:"Open the word card",title:"In a sentence · worcestershire",body:"She splashed a generous dash of Worcestershire sauce into the stew to give it a deep, tangy flavor.",clip:1},"wh-worcestershire":{src:"concept:91:words:12:hook",route:"#/word/worcestershire",cta:"Open the word card",title:"Remember it · worcestershire",body:"Spell WORCESTERSHIRE by parts: WORCESTER + SHIRE — the sauce is complex, so is the spelling."},"wo-worcestershire":{src:"lore:worcestershire:0",route:"#/word/worcestershire",cta:"Open the word card",title:"Where it comes from · worcestershire",body:"Old English Wigoraceaster + scir = shire/district"},"wd-edamame":{src:"concept:91:words:14:def",route:"#/word/edamame",cta:"Open the word card",title:"edamame",roman:"ed-uh-MAH-may",body:"young soybeans harvested while still green and tender, typically served steamed in their pods and lightly salted, popular as a snack especially in Japanese cuisine",clip:1},"wx-edamame":{src:"concept:91:words:14:ex",route:"#/word/edamame",cta:"Open the word card",title:"In a sentence · edamame",body:"At the Japanese restaurant, they snacked on lightly salted edamame while waiting for their sushi to arrive.",clip:1},"wh-edamame":{src:"concept:91:words:14:hook",route:"#/word/edamame",cta:"Open the word card",title:"Remember it · edamame",body:"EDAmame: EDA sounds like 'eat-a' — eat a bean right off the branch!"},"li-u101":{src:"concept:92:concept",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words",body:"Geographical vocabulary draws from multiple languages — Greek for landform concepts, Spanish and Portuguese for the Americas, Arabic for Middle Eastern geography, and Old Norse for Scandinavian features. Origin signals spelling."},"lc-u101-0":{src:"concept:92:cards:0",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words · Landform Words",body:"Archipelago (arkhi- + pelagos = sea) = a group of islands in a sea. Peninsula (paene = almost + insula = island) = a land almost surrounded by water. Isthmus (isthmos = neck) = a narrow land connection = I-S-T-H-M-U-S (the th and m cluster). Escarpment = a steep slope at the edge of a plateau."},"lc-u101-1":{src:"concept:92:cards:1",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words · Water Words",body:"Estuary (aestus = tide) = a tidal river mouth where fresh and salt water meet. Lagoon (Italian laguna from Latin lacuna = pool) = a shallow body of water. Fjord (Norwegian) = a narrow sea inlet between cliffs — F-J-O-R-D (the fj- cluster is pure Norse)."},"lc-u101-2":{src:"concept:92:cards:2",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words · Climate Zone Words",body:"Savanna (Spanish sabana from Taino) = a tropical grassland with scattered trees. Tundra (Russian from Finnish tunturi = treeless plain) = the Arctic treeless plain. Chaparral (Spanish chaparro = dwarf evergreen oak) = dense shrubby vegetation in dry climates."},"lc-u101-3":{src:"concept:92:cards:3",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words · Spanish/Portuguese Americas Words",body:"Canyon (cañón = large tube/pipe) = a deep gorge. Mesa (mesa = table) = a flat-topped hill. Arroyo (arroyo = stream) = a dry gully. Laguna = a lagoon. Pampa (Quechua pampa = plain) = the South American grassland. Many American landscape words are Spanish because Spanish explorers named them first."},"lc-u101-4":{src:"concept:92:cards:4",route:"#/stop/u101",cta:"Open this stop",title:"Geography & Place Words · Bee Strategy for Geography",body:"Landform words from Spanish keep -ll- (armadillo, guerrilla, vanilla) or -rr- (arroyo, sierra). Norse words may have fj- or -rd endings. Greek geography words use -graph-, -scope-, -meter-. The definition + origin together point to the right spelling pattern every time."},"uq-u101-0":{src:"unit:u101:qs:0",route:"#/stop/u101",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Geography & Place Words”?",opts:["Geographical vocabulary draws from multiple languages — Greek for landform concepts, Spanish and Portuguese for the Americas, Arabic for Middle Eastern geograph","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Geography & Place Words”."}},"uq-u101-3":{src:"unit:u101:qs:3",route:"#/stop/u101",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: the ARCH chief of the SEA holds many islands — spell out arch-i-pel-a-go like stepping stones between islands.” — which word is this hook about?",opts:["archipelago","peninsula","isthmus","escarpment"],after:"From “Geography & Place Words”."}},"wd-archipelago":{src:"concept:92:words:0:def",route:"#/word/archipelago",cta:"Open the word card",title:"archipelago",roman:"ah-rkuh-PEH-luh-goh",body:"a group of many islands in a large body of water",clip:1},"wx-archipelago":{src:"concept:92:words:0:ex",route:"#/word/archipelago",cta:"Open the word card",title:"In a sentence · archipelago",body:"The sailors navigated carefully through the archipelago, weaving between dozens of rocky islands.",clip:1},"wh-archipelago":{src:"concept:92:words:0:hook",route:"#/word/archipelago",cta:"Open the word card",title:"Remember it · archipelago",body:"ARCHipelago: the ARCH chief of the SEA holds many islands — spell out arch-i-pel-a-go like stepping stones between islands."},"wo-archipelago":{src:"lore:archipelago:0",route:"#/word/archipelago",cta:"Open the word card",title:"Where it comes from · archipelago",body:"Greek arkhi-(chief) + pelagos(sea) = chief sea (the Aegean)"},"wd-peninsula":{src:"concept:92:words:1:def",route:"#/word/peninsula",cta:"Open the word card",title:"peninsula",roman:"puh-NIH-nsuh-luh",body:"a large mass of land projecting into a body of water",clip:1},"wx-peninsula":{src:"concept:92:words:1:ex",route:"#/word/peninsula",cta:"Open the word card",title:"In a sentence · peninsula",body:"The small fishing village sat at the tip of a rocky peninsula surrounded by crashing waves on three sides.",clip:1},"wh-peninsula":{src:"concept:92:words:1:hook",route:"#/word/peninsula",cta:"Open the word card",title:"Remember it · peninsula",body:"A peninsula is 'almost an island' — pen+insula, one 'n', like a pen pointing into water."},"wo-peninsula":{src:"lore:peninsula:0",route:"#/word/peninsula",cta:"Open the word card",title:"Where it comes from · peninsula",body:"Latin paene = almost + insula = island"},"wd-isthmus":{src:"concept:92:words:2:def",route:"#/word/isthmus",cta:"Open the word card",title:"isthmus",roman:"IH-s-m-uh-s",body:"is a narrow strip of land with water on both sides",clip:1},"wx-isthmus":{src:"concept:92:words:2:ex",route:"#/word/isthmus",cta:"Open the word card",title:"In a sentence · isthmus",body:"The narrow isthmus of Panama connects North America and South America by a thin strip of land.",clip:1},"wh-isthmus":{src:"concept:92:words:2:hook",route:"#/word/isthmus",cta:"Open the word card",title:"Remember it · isthmus",body:"An isTHMus has a silent TH—think of it as the thin, quiet strip of land squeezed between two seas."},"wo-isthmus":{src:"lore:isthmus:0",route:"#/word/isthmus",cta:"Open the word card",title:"Where it comes from · isthmus",body:"Greek isthmos = neck of land"},"wd-escarpment":{src:"concept:92:words:3:def",route:"#/word/escarpment",cta:"Open the word card",title:"escarpment",roman:"eh-SKAH-rpmuhnt",body:"a long steep slope or cliff at the edge of a plateau or ridge; usually formed by erosion",clip:1},"wx-escarpment":{src:"concept:92:words:3:ex",route:"#/word/escarpment",cta:"Open the word card",title:"In a sentence · escarpment",body:"The hikers paused at the top of the escarpment to gaze over the vast valley hundreds of feet below.",clip:1},"wh-escarpment":{src:"concept:92:words:3:hook",route:"#/word/escarpment",cta:"Open the word card",title:"Remember it · escarpment",body:"An esCARP ment has a CARP-shaped sharp drop — imagine a fish leaping off a cliff"},"wo-escarpment":{src:"lore:escarpment:0",route:"#/word/escarpment",cta:"Open the word card",title:"Where it comes from · escarpment",body:"French escarpe = scarp, steep slope, from Italian scarpa = slope"},"wd-estuary":{src:"concept:92:words:4:def",route:"#/word/estuary",cta:"Open the word card",title:"estuary",roman:"EH-schoo-eh-ree",body:"the wide part of a river where it nears the sea; fresh and salt water mix",clip:1},"wx-estuary":{src:"concept:92:words:4:ex",route:"#/word/estuary",cta:"Open the word card",title:"In a sentence · estuary",body:"The biology class traveled to the estuary to observe the unique mix of plants and animals that thrive where the river meets the ocean.",clip:1},"wh-estuary":{src:"concept:92:words:4:hook",route:"#/word/estuary",cta:"Open the word card",title:"Remember it · estuary",body:"An ESTUary is where the ESTUS (tide) meets the river — it's a tidal mixing zone."},"wo-estuary":{src:"lore:estuary:0",route:"#/word/estuary",cta:"Open the word card",title:"Where it comes from · estuary",body:"Latin aestuarium = tidal inlet (aestus = tide/heat)"},"wd-lagoon":{src:"concept:92:words:5:def",route:"#/word/lagoon",cta:"Open the word card",title:"lagoon",roman:"l-uh-g-OO-n",body:"is an area of shallow water separated from the sea by sandy dunes",clip:1},"wx-lagoon":{src:"concept:92:words:5:ex",route:"#/word/lagoon",cta:"Open the word card",title:"In a sentence · lagoon",body:"The children snorkeled in the calm, crystal-clear lagoon sheltered by a ring of white sand.",clip:1},"wh-lagoon":{src:"concept:92:words:5:hook",route:"#/word/lagoon",cta:"Open the word card",title:"Remember it · lagoon",body:"A LAGOON has double O like the two round eyes of a calm, enclosed pool of water."},"wo-lagoon":{src:"lore:lagoon:0",route:"#/word/lagoon",cta:"Open the word card",title:"Where it comes from · lagoon",body:"Italian laguna = pool, from Latin lacuna = pit/pool"},"wd-bayou":{src:"concept:92:words:7:def",route:"#/word/bayou",cta:"Open the word card",title:"bayou",roman:"b-AY-oo",body:"is a marshy arm of a river usually sluggish or stagnant",clip:1},"wx-bayou":{src:"concept:92:words:7:ex",route:"#/word/bayou",cta:"Open the word card",title:"In a sentence · bayou",body:"Spanish moss hung from the cypress trees along the murky, still bayou at the edge of town.",clip:1},"wh-bayou":{src:"concept:92:words:7:hook",route:"#/word/bayou",cta:"Open the word card",title:"Remember it · bayou",body:"A BAYOU ends in -OU like the sound of surprise when you sink into that murky water: 'BAY-oo!'"},"wo-bayou":{src:"lore:bayou:0",route:"#/word/bayou",cta:"Open the word card",title:"Where it comes from · bayou",body:"Louisiana French bayou, from Choctaw bayuk = small stream"},"wd-savanna":{src:"concept:92:words:8:def",route:"#/word/savanna",cta:"Open the word card",title:"savanna",roman:"suh-VA-nuh",body:"a flat grassland in tropical or subtropical regions",clip:1},"wx-savanna":{src:"concept:92:words:8:ex",route:"#/word/savanna",cta:"Open the word card",title:"In a sentence · savanna",body:"A lone cheetah sprinted across the golden savanna as a herd of zebras scattered in every direction.",clip:1},"wh-savanna":{src:"concept:92:words:8:hook",route:"#/word/savanna",cta:"Open the word card",title:"Remember it · savanna",body:"A savanna has one 'n' in the middle — one vast, open plain with nothing to crowd it."},"wd-tundra":{src:"concept:92:words:9:def",route:"#/word/tundra",cta:"Open the word card",title:"tundra",roman:"TUH-ndruh",body:"a vast treeless plain in the Arctic regions where the subsoil is permanently frozen",clip:1},"wx-tundra":{src:"concept:92:words:9:ex",route:"#/word/tundra",cta:"Open the word card",title:"In a sentence · tundra",body:"The caribou migrated across the frozen tundra in a massive herd that stretched as far as the eye could see.",clip:1},"wh-tundra":{src:"concept:92:words:9:hook",route:"#/word/tundra",cta:"Open the word card",title:"Remember it · tundra",body:"The TUNDRA is UNDER a frozen sky — TUNDRA hides UNDER in its letters."},"wd-chaparral":{src:"concept:92:words:10:def",route:"#/word/chaparral",cta:"Open the word card",title:"chaparral",roman:"sh-a-p-ur-A-l",body:"is a dense growth of shrubs or trees",clip:1},"wx-chaparral":{src:"concept:92:words:10:ex",route:"#/word/chaparral",cta:"Open the word card",title:"In a sentence · chaparral",body:"The hikers pushed through dense chaparral, their legs scratched by the tough, wiry shrubs on the hillside.",clip:1},"wh-chaparral":{src:"concept:92:words:10:hook",route:"#/word/chaparral",cta:"Open the word card",title:"Remember it · chaparral",body:"ChaPARRal has a PARR in the middle — think of PARR as a tangled thicket of letters."},"wo-chaparral":{src:"lore:chaparral:0",route:"#/word/chaparral",cta:"Open the word card",title:"Where it comes from · chaparral",body:"Spanish 'chaparro' = dwarf evergreen oak"},"wd-taiga":{src:"concept:92:words:11:def",route:"#/word/taiga",cta:"Open the word card",title:"taiga",roman:"TY-guh",body:"The vast boreal forest biome found across northern regions of Russia, Canada, and Scandinavia, characterized by dense coniferous trees such as spruce, fir, and pine. It is the world's largest terrestrial biome and endures extremely cold winters.",clip:1},"wx-taiga":{src:"concept:92:words:11:ex",route:"#/word/taiga",cta:"Open the word card",title:"In a sentence · taiga",body:"The taiga stretches across northern Russia, filled with dense spruce and pine forests.",clip:1},"wh-taiga":{src:"concept:92:words:11:hook",route:"#/word/taiga",cta:"Open the word card",title:"Remember it · taiga",body:"The taiga is a vast forest — spell it T-A-I-G-A, like a tiger's cold home."},"wd-mesa":{src:"concept:92:words:13:def",route:"#/word/mesa",cta:"Open the word card",title:"mesa",roman:"MAY-suh",body:"flat tableland with steep edges",clip:1},"wx-mesa":{src:"concept:92:words:13:ex",route:"#/word/mesa",cta:"Open the word card",title:"In a sentence · mesa",body:"the tribe was relatively safe on the mesa but they had to descend into the valley for water",clip:1},"wh-mesa":{src:"concept:92:words:13:hook",route:"#/word/mesa",cta:"Open the word card",title:"Remember it · mesa",body:"A MESA is a TABLE in Spanish — flat on top like a dining table, one 's' keeps it sleek and level."},"wd-arroyo":{src:"concept:92:words:14:def",route:"#/word/arroyo",cta:"Open the word card",title:"arroyo",roman:"er-OY-oh",body:"a stream or brook",clip:1},"wx-arroyo":{src:"concept:92:words:14:ex",route:"#/word/arroyo",cta:"Open the word card",title:"In a sentence · arroyo",body:"After the desert rainstorm, the dry arroyo quickly filled with rushing water.",clip:1},"wh-arroyo":{src:"concept:92:words:14:hook",route:"#/word/arroyo",cta:"Open the word card",title:"Remember it · arroyo",body:"An ARROYO has double R like a rushing river roaring through a ravine."},"wd-veldt":{src:"concept:92:words:16:def",route:"#/word/veldt",cta:"Open the word card",title:"veldt",roman:"VELT",body:"elevated open grassland in southern Africa",clip:1},"wx-veldt":{src:"concept:92:words:16:ex",route:"#/word/veldt",cta:"Open the word card",title:"In a sentence · veldt",body:"Lions roamed freely across the golden veldt as the African sun dipped below the hills.",clip:1},"wh-veldt":{src:"concept:92:words:16:hook",route:"#/word/veldt",cta:"Open the word card",title:"Remember it · veldt",body:"VELDT has a silent T at the end — like the quiet grassland itself: V-E-L-D-T."},"li-u102":{src:"concept:93:concept",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary",body:"Legal and governmental vocabulary draws almost entirely from Latin — English law was conducted in Latin for centuries. These words follow strict Latin spelling rules and appear frequently in championship bees."},"lc-u102-0":{src:"concept:93:cards:0",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary · Core Legal Latin",body:"Habeas corpus (habeas = you should have + corpus = body) = the right to appear before a court. Subpoena (sub- + poena = penalty) = under penalty = a legal demand to appear. Jurisprudence (juris = of law + prudentia) = the philosophy of law."},"lc-u102-1":{src:"concept:93:cards:1",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary · Types of Government",body:"Oligarchy (oligos = few + arkhein = rule) = rule by a few. Plutocracy (ploutos = wealth + kratos) = rule by the wealthy. Theocracy (theos = god + kratos) = rule by divine authority. Kleptocracy (kleptein = steal + kratos) = rule by thieves = corrupt government."},"lc-u102-2":{src:"concept:93:cards:2",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary · Legal Process Words",body:"Adjudicate (ad- + judex = judge) = to give a judicial ruling. Promulgate (pro- + vulgare = publish) = to make known officially. Ratify (ratus + -fy) = to formally approve. Filibuster (Spanish filibustero = pirate) = obstructing legislation through extended speech."},"lc-u102-3":{src:"concept:93:cards:3",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary · Constitutional Words",body:"Plenipotentiary = a diplomat with full powers. Extraterritoriality = exemption from local law. Abrogation (ab- + rogare = ask) = repeal of a law. Promulgation = official public announcement. Bicameral (bi- + camera = chamber) = having two legislative chambers."},"lc-u102-4":{src:"concept:93:cards:4",route:"#/stop/u102",cta:"Open this stop",title:"Law & Government Vocabulary · Spelling Legal Words",body:"Habeas corpus = H-A-B-E-A-S · C-O-R-P-U-S (two-word Latin phrase). Subpoena = S-U-B-P-O-E-N-A (sub- + poena). Jurisprudence = J-U-R-I-S-P-R-U-D-E-N-C-E (-ence). Plenipotentiary = P-L-E-N-I-P-O-T-E-N-T-I-A-R-Y. These long Latin compounds spell correctly when broken into their component roots."},"uq-u102-0":{src:"unit:u102:qs:0",route:"#/stop/u102",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Law & Government Vocabulary”?",opts:["Legal and governmental vocabulary draws almost entirely from Latin — English law was conducted in Latin for centuries.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Law & Government Vocabulary”."}},"uq-u102-3":{src:"unit:u102:qs:3",route:"#/stop/u102",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ ends in -ENCE not -ANCE — it takes PRUDENCE (wisdom) to practice ▁▁▁.” — which word is this hook about?",opts:["jurisprudence","habeas corpus","subpoena","plenipotentiary"],after:"From “Law & Government Vocabulary”."}},"wd-jurisprudence":{src:"concept:93:words:0:def",route:"#/word/jurisprudence",cta:"Open the word card",title:"jurisprudence",roman:"juu-ruh-SPROO-duhns",body:"the branch of philosophy concerned with the law and the principles that lead courts to make the decisions they do",clip:1},"wx-jurisprudence":{src:"concept:93:words:0:ex",route:"#/word/jurisprudence",cta:"Open the word card",title:"In a sentence · jurisprudence",body:"Uncle Rahul studies jurisprudence, asking why judges decide cases the way they do.",clip:1},"wh-jurisprudence":{src:"concept:93:words:0:hook",route:"#/word/jurisprudence",cta:"Open the word card",title:"Remember it · jurisprudence",body:"JURISPRUDENCE ends in -ENCE not -ANCE — it takes PRUDENCE (wisdom) to practice jurisPRUDENCE."},"wo-jurisprudence":{src:"lore:jurisprudence:0",route:"#/word/jurisprudence",cta:"Open the word card",title:"Where it comes from · jurisprudence",body:"Latin jurisprudentia = knowledge of law, from jus = law + prudentia = knowledge"},"wd-plenipotentiary":{src:"concept:93:words:3:def",route:"#/word/plenipotentiary",cta:"Open the word card",title:"plenipotentiary",roman:"plen-ih-puh-TEN-shee-ehr-ee",body:"a diplomat who is fully authorized to represent his or her government",clip:1},"wx-plenipotentiary":{src:"concept:93:words:3:ex",route:"#/word/plenipotentiary",cta:"Open the word card",title:"In a sentence · plenipotentiary",body:"The plenipotentiary arrived in the capital city with the authority to sign the peace treaty on behalf of her entire nation.",clip:1},"wh-plenipotentiary":{src:"concept:93:words:3:hook",route:"#/word/plenipotentiary",cta:"Open the word card",title:"Remember it · plenipotentiary",body:"PLENI (full) + POTENT (powerful): someone with FULL POWER to negotiate"},"wo-plenipotentiary":{src:"lore:plenipotentiary:0",route:"#/word/plenipotentiary",cta:"Open the word card",title:"Where it comes from · plenipotentiary",body:"Latin plenus = full + potentia = power"},"wd-adjudicate":{src:"concept:93:words:4:def",route:"#/word/adjudicate",cta:"Open the word card",title:"adjudicate",roman:"uh-JOO-dih-kayt",body:"put on trial or hear a case and sit as the judge at the trial of; to make a formal judgment",clip:1},"wx-adjudicate":{src:"concept:93:words:4:ex",route:"#/word/adjudicate",cta:"Open the word card",title:"In a sentence · adjudicate",body:"The experienced judge was asked to adjudicate the dispute between the two competing robotics teams at the regional competition.",clip:1},"wh-adjudicate":{src:"concept:93:words:4:hook",route:"#/word/adjudicate",cta:"Open the word card",title:"Remember it · adjudicate",body:"A JUDGE adjudicates — both share judic"},"wo-adjudicate":{src:"lore:adjudicate:0",route:"#/word/adjudicate",cta:"Open the word card",title:"Where it comes from · adjudicate",body:"Latin adjudicare = to award, from ad + judicare = to judge"},"wd-promulgate":{src:"concept:93:words:5:def",route:"#/word/promulgate",cta:"Open the word card",title:"promulgate",roman:"proh-MUH-lgayt",body:"state or announce",clip:1},"wx-promulgate":{src:"concept:93:words:5:ex",route:"#/word/promulgate",cta:"Open the word card",title:"In a sentence · promulgate",body:"The school board voted to promulgate new guidelines about technology use in classrooms before the new semester began.",clip:1},"wh-promulgate":{src:"concept:93:words:5:hook",route:"#/word/promulgate",cta:"Open the word card",title:"Remember it · promulgate",body:"PRO-mulgators speak FORTH to make laws public"},"wo-promulgate":{src:"lore:promulgate:0",route:"#/word/promulgate",cta:"Open the word card",title:"Where it comes from · promulgate",body:"Latin promulgare (to make public) from pro (forth) + mulgere (to make known)"},"wd-ratify":{src:"concept:93:words:6:def",route:"#/word/ratify",cta:"Open the word card",title:"ratify",roman:"RA-tuh-feye",body:"approve and express assent, responsibility, or obligation",clip:1},"wx-ratify":{src:"concept:93:words:6:ex",route:"#/word/ratify",cta:"Open the word card",title:"In a sentence · ratify",body:"Our club must ratify the new rules before they can take effect next term.",clip:1},"wh-ratify":{src:"concept:93:words:6:hook",route:"#/word/ratify",cta:"Open the word card",title:"Remember it · ratify",body:"RATIFY: one T — to make (fy) something fixed (rati), r-a-t-i-f-y."},"wd-filibuster":{src:"concept:93:words:7:def",route:"#/word/filibuster",cta:"Open the word card",title:"filibuster",roman:"FIH-luh-buh-ster",body:"a legislator who gives long speeches in an effort to delay or obstruct legislation that he (or she) opposes",clip:1},"wx-filibuster":{src:"concept:93:words:7:ex",route:"#/word/filibuster",cta:"Open the word card",title:"In a sentence · filibuster",body:"The senator launched a filibuster that lasted nearly twelve hours, reading recipes aloud to stall the vote.",clip:1},"wh-filibuster":{src:"concept:93:words:7:hook",route:"#/word/filibuster",cta:"Open the word card",title:"Remember it · filibuster",body:"A FILIbuster BUSTS the Senate schedule — one L, like one senator talking forever."},"wd-gerrymander":{src:"concept:93:words:8:def",route:"#/word/gerrymander",cta:"Open the word card",title:"gerrymander",roman:"j-EH-r-ee-m-a-n-d-ur",body:"is dividing election districts to suit one group or party",clip:1},"wx-gerrymander":{src:"concept:93:words:8:ex",route:"#/word/gerrymander",cta:"Open the word card",title:"In a sentence · gerrymander",body:"Critics accused the legislature of trying to gerrymander the district boundaries to guarantee their party's victory in the next election.",clip:1},"wh-gerrymander":{src:"concept:93:words:8:hook",route:"#/word/gerrymander",cta:"Open the word card",title:"Remember it · gerrymander",body:"Governor GERRY drew a district shaped like a SALAMANDER — GERRY+mander = GERRYMANDER."},"wo-gerrymander":{src:"lore:gerrymander:0",route:"#/word/gerrymander",cta:"Open the word card",title:"Where it comes from · gerrymander",body:"Elbridge Gerry (governor) + salamander (shape of the district he drew)"},"wd-oligarchy":{src:"concept:93:words:9:def",route:"#/word/oligarchy",cta:"Open the word card",title:"oligarchy",roman:"AH-luh-gah-rkee",body:"a political system governed by a few people",clip:1},"wx-oligarchy":{src:"concept:93:words:9:ex",route:"#/word/oligarchy",cta:"Open the word card",title:"In a sentence · oligarchy",body:"The revolution was sparked by citizens who were tired of living under an oligarchy where three wealthy families made all the laws.",clip:1},"wh-oligarchy":{src:"concept:93:words:9:hook",route:"#/word/oligarchy",cta:"Open the word card",title:"Remember it · oligarchy",body:"OLIGARCHy — an OLIGARCH rules with FEW (oligos) in an ARCH of power."},"wo-oligarchy":{src:"lore:oligarchy:0",route:"#/word/oligarchy",cta:"Open the word card",title:"Where it comes from · oligarchy",body:"Greek oligos = few + arkhein = to rule"},"wd-meritocracy":{src:"concept:93:words:13:def",route:"#/word/meritocracy",cta:"Open the word card",title:"meritocracy",roman:"meh-rih-TAW-kruh-see",body:"a form of social system in which power goes to those with superior intellects",clip:1},"wx-meritocracy":{src:"concept:93:words:13:ex",route:"#/word/meritocracy",cta:"Open the word card",title:"In a sentence · meritocracy",body:"In a true meritocracy, the hardest-working and most talented people rise to the top.",clip:1},"wh-meritocracy":{src:"concept:93:words:13:hook",route:"#/word/meritocracy",cta:"Open the word card",title:"Remember it · meritocracy",body:"MERITOCRACY = MERIT + OCRACY (like democracy) — those who EARN it RULE it, spelled just as it sounds."},"wo-meritocracy":{src:"lore:meritocracy:0",route:"#/word/meritocracy",cta:"Open the word card",title:"Where it comes from · meritocracy",body:"Latin meritum = earned + Greek kratos = power, rule"},"wd-abrogation":{src:"concept:93:words:14:def",route:"#/word/abrogation",cta:"Open the word card",title:"abrogation",roman:"a-bruh-GAY-shuhn",body:"the act of abrogating; an official or legal cancellation",clip:1},"wx-abrogation":{src:"concept:93:words:14:ex",route:"#/word/abrogation",cta:"Open the word card",title:"In a sentence · abrogation",body:"The abrogation of the old trade agreement sent shock waves through the economies of both countries.",clip:1},"wh-abrogation":{src:"concept:93:words:14:hook",route:"#/word/abrogation",cta:"Open the word card",title:"Remember it · abrogation",body:"Abrogation cancels laws — it's an AB-ROG-ATION, with ROG like 'rogue' tossing the law aside."},"wo-abrogation":{src:"lore:abrogation:0",route:"#/word/abrogation",cta:"Open the word card",title:"Where it comes from · abrogation",body:"Latin abrogatio = ab-(away)+rogare(to propose a law)"},"wd-bicameral":{src:"concept:93:words:15:def",route:"#/word/bicameral",cta:"Open the word card",title:"bicameral",roman:"by-KAM-er-ul",body:"composed of two legislative bodies",clip:1},"wx-bicameral":{src:"concept:93:words:15:ex",route:"#/word/bicameral",cta:"Open the word card",title:"In a sentence · bicameral",body:"the bicameral heart of a fish",clip:1},"wh-bicameral":{src:"concept:93:words:15:hook",route:"#/word/bicameral",cta:"Open the word card",title:"Remember it · bicameral",body:"BICAMERAL: TWO CAMERAs in one legislature — BI + CAMERA + L, one C not two."},"wo-bicameral":{src:"lore:bicameral:0",route:"#/word/bicameral",cta:"Open the word card",title:"Where it comes from · bicameral",body:"Latin bi = two + camera = chamber"},"li-u103":{src:"concept:104:concept",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology",body:"Mythology generated hundreds of English words through the names of gods, heroes, and places. These words often have unusual spellings — because they come from Greek or Latin proper names, not from common roots."},"lc-u103-0":{src:"concept:104:cards:0",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology · Gods → Common Nouns",body:"Panic = from Pan (Greek goat-god who caused sudden terror). Volcano = from Vulcan (Roman god of fire). Cereal = from Ceres (Roman goddess of grain). Music = from the Muses (nine Greek goddesses of arts). Ocean = from Oceanus (the Titan who surrounded the world)."},"lc-u103-1":{src:"concept:104:cards:1",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology · Heroes → Adjectives",body:"Herculean = of Hercules = requiring enormous strength. Promethean = of Prometheus = boldly creative, fire-stealing. Quixotic = of Don Quixote (literary, not mythological) = impractically idealistic. Odyssean = of Odysseus = involving a long, difficult journey."},"lc-u103-2":{src:"concept:104:cards:2",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology · Places → Words",body:"Labyrinth = from the Labyrinth of the Minotaur in Crete. Marathon = from the town of Marathon (the messenger ran 26 miles to Athens). Laconic = from Laconia/Sparta (Spartans were famous for brief speech). Draconian = from Draco (Athenian lawmaker famous for harsh laws)."},"lc-u103-3":{src:"concept:104:cards:3",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology · Planets & Elements",body:"Mercury (planet + element) = from Mercury, messenger god. Venus = from Venus, goddess of love. Mars = from Mars, god of war. Plutonium = from Pluto, god of the underworld. Titanium = from the Titans. Helium = from Helios, god of the sun (discovered in the sun's spectrum first)."},"lc-u103-4":{src:"concept:104:cards:4",route:"#/stop/u103",cta:"Open this stop",title:"Words from Greek & Roman Mythology · Spelling Mythology Words",body:"Promethean = P-R-O-M-E-T-H-E-A-N (-th- Greek theta). Herculean = H-E-R-C-U-L-E-A-N (-ean suffix). Labyrinth = L-A-B-Y-R-I-N-T-H (y as vowel, Greek). Draconian = D-R-A-C-O-N-I-A-N (from Drakōn). Siren = S-I-R-E-N (ei from Greek Seirēn)."},"uq-u103-0":{src:"unit:u103:qs:0",route:"#/stop/u103",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Words from Greek & Roman Mythology”?",opts:["Mythology generated hundreds of English words through the names of gods, heroes, and places.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Words from Greek & Roman Mythology”."}},"uq-u103-3":{src:"unit:u103:qs:3",route:"#/stop/u103",cta:"Open this stop",title:"Whose hook?",play:{q:"“Prometheus stole fire — spell his name with EAN at the end, like a heroic LEAN forward into flames.” — which word is this hook about?",opts:["promethean","herculean","quixotic","labyrinth"],after:"From “Words from Greek & Roman Mythology”."}},"wd-marathon":{src:"concept:104:words:4:def",route:"#/word/marathon",cta:"Open the word card",title:"marathon",roman:"MEH-ruh-thahn",body:"any long and arduous undertaking",clip:1},"wx-marathon":{src:"concept:104:words:4:ex",route:"#/word/marathon",cta:"Open the word card",title:"In a sentence · marathon",body:"Studying for finals felt like a marathon as Jaylen sat at his desk for six straight hours reviewing every chapter.",clip:1},"wh-marathon":{src:"concept:104:words:4:hook",route:"#/word/marathon",cta:"Open the word card",title:"Remember it · marathon",body:"MARAthon — a MARA-vel of endurance; think of the messenger who ran from MARA-thon to Athens"},"wo-marathon":{src:"lore:marathon:0",route:"#/word/marathon",cta:"Open the word card",title:"Where it comes from · marathon",body:"Greek Marathon, the Greek plain where Athenians defeated Persians in 490 BC"},"wd-laconic":{src:"concept:104:words:5:def",route:"#/word/laconic",cta:"Open the word card",title:"laconic",roman:"l-ah-k-AH-n-ih-k",body:"is using few words being concise",clip:1},"wx-laconic":{src:"concept:104:words:5:ex",route:"#/word/laconic",cta:"Open the word card",title:"In a sentence · laconic",body:"Coach Rivera was famously laconic before big games, offering her team nothing more than a quiet nod and the words 'You know what to do,' yet somehow those five words inspired more confidence than any long speech ever could.",clip:1},"wh-laconic":{src:"concept:104:words:5:hook",route:"#/word/laconic",cta:"Open the word card",title:"Remember it · laconic",body:"Spartans from LACONIA said little — laconic means little talk."},"wo-laconic":{src:"lore:laconic:0",route:"#/word/laconic",cta:"Open the word card",title:"Where it comes from · laconic",body:"Greek Lakon = a Spartan (Laconians were famous for brief speech)"},"wd-draconian":{src:"concept:104:words:6:def",route:"#/word/draconian",cta:"Open the word card",title:"draconian",roman:"dray-KOH-nee-uhn",body:"of or relating to Draco or his harsh code of laws",clip:1},"wx-draconian":{src:"concept:104:words:6:ex",route:"#/word/draconian",cta:"Open the word card",title:"In a sentence · draconian",body:"The principal's draconian rule that students could not speak at all during lunch made the cafeteria feel like a prison.",clip:1},"wh-draconian":{src:"concept:104:words:6:hook",route:"#/word/draconian",cta:"Open the word card",title:"Remember it · draconian",body:"DRAConian laws DRAG you down with their harshness"},"wo-draconian":{src:"lore:draconian:0",route:"#/word/draconian",cta:"Open the word card",title:"Where it comes from · draconian",body:"Greek Drakon = Athenian lawgiver known for harsh laws"},"wd-siren":{src:"concept:104:words:8:def",route:"#/word/siren",cta:"Open the word card",title:"siren",roman:"SEYE-ruhn",body:"a sea nymph (part woman and part bird) supposed to lure sailors to destruction on the rocks where the nymphs lived",clip:1},"wx-siren":{src:"concept:104:words:8:ex",route:"#/word/siren",cta:"Open the word card",title:"In a sentence · siren",body:"Odysseus ordered his crew to plug their ears so they would not hear the Siren's fatal song",clip:1},"wh-siren":{src:"concept:104:words:8:hook",route:"#/word/siren",cta:"Open the word card",title:"Remember it · siren",body:"A SIREN lures with her voice—the 'i' in the middle is the eye that hypnotizes sailors."},"wd-volcano":{src:"concept:104:words:9:def",route:"#/word/volcano",cta:"Open the word card",title:"volcano",roman:"vah-LKAY-noh",body:"a fissure in the earth's crust (or in the surface of some other planet) through which molten lava and gases erupt",clip:1},"wx-volcano":{src:"concept:104:words:9:ex",route:"#/word/volcano",cta:"Open the word card",title:"In a sentence · volcano",body:"Lava poured down the volcano's slope, glowing orange against the dark night sky.",clip:1},"wh-volcano":{src:"concept:104:words:9:hook",route:"#/word/volcano",cta:"Open the word card",title:"Remember it · volcano",body:"VOL-CA-NO: think 'VOLatile CANon of lava NO one can stop' — it opens with VOL, not VUL."},"wo-volcano":{src:"lore:volcano:0",route:"#/word/volcano",cta:"Open the word card",title:"Where it comes from · volcano",body:"Italian vulcano, from Latin Vulcanus = Vulcan, Roman god of fire"},"wd-cereal":{src:"concept:104:words:10:def",route:"#/word/cereal",cta:"Open the word card",title:"cereal",roman:"s-IH-r-ee-uh-l",body:"a prepared food of grain such as oatmeal or cornflakes eaten especially for breakfast",clip:1},"wx-cereal":{src:"concept:104:words:10:ex",route:"#/word/cereal",cta:"Open the word card",title:"In a sentence · cereal",body:"Before the big exam, Daria poured herself a bowl of whole-grain cereal, knowing that a nutritious breakfast would help her stay alert and focused throughout the long morning.",clip:1},"wh-cereal":{src:"concept:104:words:10:hook",route:"#/word/cereal",cta:"Open the word card",title:"Remember it · cereal",body:"CEREAL comes from CERES the grain goddess — it starts with CE like the goddess, not SE like a TV serial."},"wo-cereal":{src:"lore:cereal:0",route:"#/word/cereal",cta:"Open the word card",title:"Where it comes from · cereal",body:"Latin Ceres = Roman goddess of grain + -alis = relating to"},"wd-ocean":{src:"concept:104:words:12:def",route:"#/word/ocean",cta:"Open the word card",title:"ocean",roman:"OH-shuhn",body:"a large body of water constituting a principal part of the hydrosphere",clip:1},"wx-ocean":{src:"concept:104:words:12:ex",route:"#/word/ocean",cta:"Open the word card",title:"In a sentence · ocean",body:"Standing at the cliff's edge, she stared out at the vast ocean stretching endlessly to the horizon.",clip:1},"wh-ocean":{src:"concept:104:words:12:hook",route:"#/word/ocean",cta:"Open the word card",title:"Remember it · ocean",body:"The OCEAN ends in '-ean' — think 'the sea can' hold the spelling o-c-e-a-n."},"wx-chaos":{src:"concept:104:words:13:ex",route:"#/word/chaos",cta:"Open the word card",title:"In a sentence · chaos",body:"When the fire alarm went off during lunch, the cafeteria erupted into complete chaos as students scrambled for the exits.",clip:1},"wh-chaos":{src:"concept:104:words:13:hook",route:"#/word/chaos",cta:"Open the word card",title:"Remember it · chaos",body:"CHAOS starts with CH not K — remember: Complete Havoc And Overwhelming Scramble."},"li-u104":{src:"concept:105:concept",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-)",body:"Time vocabulary extends far beyond chron-. Latin tempus, Greek aion, and hora all generate time words — plus poetic and philosophical time concepts that appear in advanced vocabulary rounds."},"lc-u104-0":{src:"concept:105:cards:0",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-) · ephemeral & transient",body:"Ephemeral (epi- + hemera = day) = lasting only a day = short-lived. Transient (trans- + ire = go across) = passing across quickly = temporary. Fleeting (Old English fleon = to flee) = passing quickly. Momentary (momentum = movement) = lasting only a moment. All describe brevity of time."},"lc-u104-1":{src:"concept:105:cards:1",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-) · tempus (Latin time)",body:"Temporal (tempus = time) = relating to time (vs spiritual). Temporary = lasting for a limited time. Contemporary (con- + tempus) = existing at the same time. Extemporaneous (ex tempore = out of the moment) = spoken without preparation."},"lc-u104-2":{src:"concept:105:cards:2",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-) · aion / aevum (age/era)",body:"Aeon (Greek aion) = an immeasurably long period. Medieval (medi- = middle + aevum = age) = of the middle ages. Primeval (prim- = first + aevum) = of the earliest age. Coeval (co- + aevum) = of the same age/period. Longevity (longus = long + aevum = age) = long life."},"lc-u104-3":{src:"concept:105:cards:3",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-) · hora (hour/season)",body:"Horology (hora + -logy) = the study and making of clocks. Horoscope (hora + -scope) = looking at the birth hour. Ephemeral blends epi- (upon) + hemera (day, from Greek goddess Hemera of daylight). Diurnal (diurnus from dies = day) = occurring during the day or daily."},"lc-u104-4":{src:"concept:105:cards:4",route:"#/stop/u104",cta:"Open this stop",title:"Words About Time (Beyond chron-) · Spelling Time Words",body:"Ephemeral = E-P-H-E-M-E-R-A-L (-ph- Greek signal; -er- not -or-). Extemporaneous = E-X-T-E-M-P-O-R-A-N-E-O-U-S (from ex tempore). Contemporary = C-O-N-T-E-M-P-O-R-A-R-Y (con + tempor + -ary). Medieval = M-E-D-I-E-V-A-L (-ie- not -ei- — the e comes from aevum, not from the ie/ei rule)."},"uq-u104-0":{src:"unit:u104:qs:0",route:"#/stop/u104",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Words About Time (Beyond chron-)”?",opts:["Time vocabulary extends far beyond chron-.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Words About Time (Beyond chron-)”."}},"uq-u104-3":{src:"unit:u104:qs:3",route:"#/stop/u104",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: 'Every Petal Has Every Morning Erased, Really A Loss' — beauty gone by dawn.” — which word is this hook about?",opts:["ephemeral","transient","momentary","temporal"],after:"From “Words About Time (Beyond chron-)”."}},"wd-momentary":{src:"concept:105:words:2:def",route:"#/word/momentary",cta:"Open the word card",title:"momentary",roman:"MOH-muh-nteh-ree",body:"lasting for a markedly brief time",clip:1},"wx-momentary":{src:"concept:105:words:2:ex",route:"#/word/momentary",cta:"Open the word card",title:"In a sentence · momentary",body:"The momentary flash of lightning lit up the entire night sky so brilliantly that everyone standing on the porch gasped in surprise before darkness returned.",clip:1},"wh-momentary":{src:"concept:105:words:2:hook",route:"#/word/momentary",cta:"Open the word card",title:"Remember it · momentary",body:"A MOMENTARY thing relates to a MOMENT — keep the -ARY ending like 'temporary.'"},"wo-momentary":{src:"lore:momentary:0",route:"#/word/momentary",cta:"Open the word card",title:"Where it comes from · momentary",body:"Latin momentarius = of a moment"},"wd-temporal":{src:"concept:105:words:3:def",route:"#/word/temporal",cta:"Open the word card",title:"temporal",roman:"TEH-mper-uhl",body:"the semantic role of the noun phrase that designates the time of the state or action denoted by the verb",clip:1},"wx-temporal":{src:"concept:105:words:3:ex",route:"#/word/temporal",cta:"Open the word card",title:"In a sentence · temporal",body:"temporal matters of but fleeting moment",clip:1},"wh-temporal":{src:"concept:105:words:3:hook",route:"#/word/temporal",cta:"Open the word card",title:"Remember it · temporal",body:"TEMPORAL relates to time — it holds TEMPOR(ary) inside, reminding you that time is always fleeting."},"wo-temporal":{src:"lore:temporal:0",route:"#/word/temporal",cta:"Open the word card",title:"Where it comes from · temporal",body:"Latin temporalis = of time, from tempus = time"},"wd-temporary":{src:"concept:105:words:4:def",route:"#/word/temporary",cta:"Open the word card",title:"temporary",roman:"TEH-mper-eh-ree",body:"lasting only for a short time, not permanent",clip:1},"wx-temporary":{src:"concept:105:words:4:ex",route:"#/word/temporary",cta:"Open the word card",title:"In a sentence · temporary",body:"We used a temporary shelter until the new tent arrived on Friday.",clip:1},"wh-temporary":{src:"concept:105:words:4:hook",route:"#/word/temporary",cta:"Open the word card",title:"Remember it · temporary",body:"Temporary has an A before the R — think 'A temp works A while' to remember the -ary ending."},"wo-temporary":{src:"lore:temporary:0",route:"#/word/temporary",cta:"Open the word card",title:"Where it comes from · temporary",body:"Latin tempus = time"},"wd-contemporary":{src:"concept:105:words:5:def",route:"#/word/contemporary",cta:"Open the word card",title:"contemporary",roman:"kuh-NTEH-mper-eh-ree",body:"a person of nearly the same age as another",clip:1},"wx-contemporary":{src:"concept:105:words:5:ex",route:"#/word/contemporary",cta:"Open the word card",title:"In a sentence · contemporary",body:"contemporary trends in design",clip:1},"wh-contemporary":{src:"concept:105:words:5:hook",route:"#/word/contemporary",cta:"Open the word card",title:"Remember it · contemporary",body:"A CONTEMPORARY shares your TIME — find TEMPOR (time) hiding inside, then add '-ary'."},"wo-contemporary":{src:"lore:contemporary:0",route:"#/word/contemporary",cta:"Open the word card",title:"Where it comes from · contemporary",body:"Latin contemporarius = of the same time"},"wd-aeon":{src:"concept:105:words:7:def",route:"#/word/aeon",cta:"Open the word card",title:"aeon",roman:"EE-on",body:"an extremely long period of time",clip:1},"wx-aeon":{src:"concept:105:words:7:ex",route:"#/word/aeon",cta:"Open the word card",title:"In a sentence · aeon",body:"Those chalk cliffs took an aeon to form, layer by layer beneath an ancient sea.",clip:1},"wh-aeon":{src:"concept:105:words:7:hook",route:"#/word/aeon",cta:"Open the word card",title:"Remember it · aeon",body:"AEON has the fancy AE at the start — the extra A stretches the word out, just like an aeon stretches out time."},"wd-medieval":{src:"concept:105:words:8:def",route:"#/word/medieval",cta:"Open the word card",title:"medieval",roman:"mih-DEE-vuhl",body:"relating to or belonging to the Middle Ages",clip:1},"wx-medieval":{src:"concept:105:words:8:ex",route:"#/word/medieval",cta:"Open the word card",title:"In a sentence · medieval",body:"The students built a medieval castle replica complete with a drawbridge and turrets for their history class project on the feudal system.",clip:1},"wh-medieval":{src:"concept:105:words:8:hook",route:"#/word/medieval",cta:"Open the word card",title:"Remember it · medieval",body:"MEDIEval — MEDI means MIDDLE; the MEDIEval era is the MIDDLE age of history"},"wo-medieval":{src:"lore:medieval:0",route:"#/word/medieval",cta:"Open the word card",title:"Where it comes from · medieval",body:"Latin medius = middle + aevum = age, era"},"wd-primeval":{src:"concept:105:words:9:def",route:"#/word/primeval",cta:"Open the word card",title:"primeval",roman:"preye-MEE-vuhl",body:"having existed from the beginning; in an earliest or original stage or state",clip:1},"wx-primeval":{src:"concept:105:words:9:ex",route:"#/word/primeval",cta:"Open the word card",title:"In a sentence · primeval",body:"The hikers stood in silence at the edge of the primeval forest, awed by the towering ancient trees whose roots had spread through the dark soil for thousands of uninterrupted years.",clip:1},"wh-primeval":{src:"concept:105:words:9:hook",route:"#/word/primeval",cta:"Open the word card",title:"Remember it · primeval",body:"PRIMEVAL = PRIME + EVAL(uation of the first age) — think 'prime evil' ancient darkness."},"wo-primeval":{src:"lore:primeval:0",route:"#/word/primeval",cta:"Open the word card",title:"Where it comes from · primeval",body:"Latin primus = first + aevum = age"},"wx-coeval":{src:"concept:105:words:10:ex",route:"#/word/coeval",cta:"Open the word card",title:"In a sentence · coeval",body:"Shakespeare and Galileo were nearly coeval, both shaping history during the remarkable late sixteenth century.",clip:1},"wh-coeval":{src:"concept:105:words:10:hook",route:"#/word/coeval",cta:"Open the word card",title:"Remember it · coeval",body:"COEVAL = same AGE (aevum) — two people are coeval when they share the same era, spelled co-EV-AL."},"wd-longevity":{src:"concept:105:words:11:def",route:"#/word/longevity",cta:"Open the word card",title:"longevity",roman:"law-NJEH-vuh-tee",body:"duration of service",clip:1},"wx-longevity":{src:"concept:105:words:11:ex",route:"#/word/longevity",cta:"Open the word card",title:"In a sentence · longevity",body:"her longevity as a star",clip:1},"wh-longevity":{src:"concept:105:words:11:hook",route:"#/word/longevity",cta:"Open the word card",title:"Remember it · longevity",body:"LONGEVITY means a LONG life with VITALITY — spot the word VITA (life) hiding inside: long-VITY."},"wo-longevity":{src:"lore:longevity:0",route:"#/word/longevity",cta:"Open the word card",title:"Where it comes from · longevity",body:"Latin longus = long + aevum = age/life"},"wd-horology":{src:"concept:105:words:12:def",route:"#/word/horology",cta:"Open the word card",title:"horology",roman:"hoh-ROL-oh-jee",body:"the art of designing and making clocks",clip:1},"wx-horology":{src:"concept:105:words:12:ex",route:"#/word/horology",cta:"Open the word card",title:"In a sentence · horology",body:"She studied horology at a Swiss institute before opening her own clock-repair shop.",clip:1},"wh-horology":{src:"concept:105:words:12:hook",route:"#/word/horology",cta:"Open the word card",title:"Remember it · horology",body:"HOROLOGY = study of HOURS — one R, like one hand on the clock face."},"wo-horology":{src:"lore:horology:0",route:"#/word/horology",cta:"Open the word card",title:"Where it comes from · horology",body:"Greek hora = hour + logos = study"},"wd-diurnal":{src:"concept:105:words:13:def",route:"#/word/diurnal",cta:"Open the word card",title:"diurnal",roman:"deye-UR-nuhl",body:"of or belonging to or active during the day",clip:1},"wx-diurnal":{src:"concept:105:words:13:ex",route:"#/word/diurnal",cta:"Open the word card",title:"In a sentence · diurnal",body:"Unlike owls, which are nocturnal hunters, eagles are diurnal birds that soar and hunt only while the sun is shining.",clip:1},"wh-diurnal":{src:"concept:105:words:13:hook",route:"#/word/diurnal",cta:"Open the word card",title:"Remember it · diurnal",body:"diURNal — contains URN; think of the sun as an URN pouring light during the DAY."},"wd-nocturnal":{src:"concept:105:words:14:def",route:"#/word/nocturnal",cta:"Open the word card",title:"nocturnal",roman:"n-ah-k-t-UR-n-uh-l",body:"is of or pertaining to the night",clip:1},"wx-nocturnal":{src:"concept:105:words:14:ex",route:"#/word/nocturnal",cta:"Open the word card",title:"In a sentence · nocturnal",body:"nocturnal animals are active at night",clip:1},"wh-nocturnal":{src:"concept:105:words:14:hook",route:"#/word/nocturnal",cta:"Open the word card",title:"Remember it · nocturnal",body:"NOCTURNal — think NOCTURNE, the night music; both start with NOCTUR-"},"wo-nocturnal":{src:"lore:nocturnal:0",route:"#/word/nocturnal",cta:"Open the word card",title:"Where it comes from · nocturnal",body:"Latin nox/noctis = night"},"wd-evanescent":{src:"concept:105:words:15:def",route:"#/word/evanescent",cta:"Open the word card",title:"evanescent",roman:"eh-vuh-NEH-suhnt",body:"tending to vanish like vapor; quickly fading or disappearing",clip:1},"wx-evanescent":{src:"concept:105:words:15:ex",route:"#/word/evanescent",cta:"Open the word card",title:"In a sentence · evanescent",body:"The evanescent rainbow disappeared just moments after the storm clouds parted, leaving only a grey sky behind.",clip:1},"wh-evanescent":{src:"concept:105:words:15:hook",route:"#/word/evanescent",cta:"Open the word card",title:"Remember it · evanescent",body:"EVANESCent — it EVANishes like an effervESCEnt bubble"},"wo-evanescent":{src:"lore:evanescent:0",route:"#/word/evanescent",cta:"Open the word card",title:"Where it comes from · evanescent",body:"Latin evanescere = to vanish, from e- = out + vanescere = to become empty, from vanus = empty"},"li-u105":{src:"concept:106:concept",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity",body:"Size and quantity vocabulary comes from both number prefixes (already covered) and from Latin and Greek roots for big/small, many/few. These combine with other roots to make precise measurement words."},"lc-u105-0":{src:"concept:106:cards:0",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity · Tiny Words",body:"Minuscule (minusculus = rather small) = tiny — NOT miniscule (a misspelling caused by confusing with mini-). Infinitesimal (infinitus = without end + -esimal = fraction) = immeasurably tiny. Diminutive (diminuere = lessen) = very small. Microscopic = visible only under a microscope."},"lc-u105-1":{src:"concept:106:cards:1",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity · Large Words",body:"Colossal (from the Colossus of Rhodes) = enormous. Titanic (from the Titans) = of enormous size and power. Gargantuan (from Gargantua, Rabelais' giant character) = enormously large. Prodigious (prodigium = omen) = remarkably large in extent."},"lc-u105-2":{src:"concept:106:cards:2",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity · Many & Few",body:"Multitudinous (multitudo = great number) = very numerous. Myriad (myrioi = ten thousand) = a very large but indefinite number (technically 10,000 in Greek). Plethora (plethora = fullness) = an excessive amount. Paucity (paucus = few) = a small number."},"lc-u105-3":{src:"concept:106:cards:3",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity · Measurement Words",body:"Infinitesimal = approaching zero. Exponential = growing by multiplication of itself. Logarithmic = growing by addition to the exponent. Negligible (neglegere = to disregard) = too small to matter. Incommensurable (in- + com- + mensura = measure) = not able to be measured against each other."},"lc-u105-4":{src:"concept:106:cards:4",route:"#/stop/u105",cta:"Open this stop",title:"Words About Size & Quantity · Spelling Size Words",body:"Minuscule = M-I-N-U-S-C-U-L-E (-us- not -is-). Infinitesimal = I-N-F-I-N-I-T-E-S-I-M-A-L (-esimal). Gargantuan = G-A-R-G-A-N-T-U-A-N. Multitudinous = M-U-L-T-I-T-U-D-I-N-O-U-S. Myriad = M-Y-R-I-A-D (y as vowel — Greek!)."},"uq-u105-0":{src:"unit:u105:qs:0",route:"#/stop/u105",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Words About Size & Quantity”?",opts:["Size and quantity vocabulary comes from both number prefixes (already covered) and from Latin and Greek roots for big/small, many/few.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Words About Size & Quantity”."}},"uq-u105-3":{src:"unit:u105:qs:3",route:"#/stop/u105",cta:"Open this stop",title:"Whose hook?",play:{q:"“Think MINUS — ▁▁▁ means less than tiny; don't spell it with an I like 'mini'” — which word is this hook about?",opts:["minuscule","infinitesimal","diminutive","microscopic"],after:"From “Words About Size & Quantity”."}},"wd-minuscule":{src:"concept:106:words:0:def",route:"#/word/minuscule",cta:"Open the word card",title:"minuscule",roman:"m-IH-n-uh-s-k-y-oo-l",body:"the characters that were once kept in bottom half of a compositor's type case; also means extremely small",clip:1},"wx-minuscule":{src:"concept:106:words:0:ex",route:"#/word/minuscule",cta:"Open the word card",title:"In a sentence · minuscule",body:"The scientist examined a minuscule speck of dust under the powerful microscope, astonished that something so incredibly tiny could contain thousands of microscopic organisms.",clip:1},"wh-minuscule":{src:"concept:106:words:0:hook",route:"#/word/minuscule",cta:"Open the word card",title:"Remember it · minuscule",body:"Think MINUS — minuscule means less than tiny; don't spell it with an I like 'mini'"},"wo-minuscule":{src:"lore:minuscule:0",route:"#/word/minuscule",cta:"Open the word card",title:"Where it comes from · minuscule",body:"Latin minusculus = rather small, from minus = less"},"wd-infinitesimal":{src:"concept:106:words:1:def",route:"#/word/infinitesimal",cta:"Open the word card",title:"infinitesimal",roman:"ih-nfih-nih-TEH-sih-muhl",body:"extremely small; far too tiny to see or measure easily",clip:1},"wx-infinitesimal":{src:"concept:106:words:1:ex",route:"#/word/infinitesimal",cta:"Open the word card",title:"In a sentence · infinitesimal",body:"Under the microscope we saw infinitesimal specks of pollen drifting across the glass slide.",clip:1},"wh-infinitesimal":{src:"concept:106:words:1:hook",route:"#/word/infinitesimal",cta:"Open the word card",title:"Remember it · infinitesimal",body:"INFINITESIMAl: spot FINITE inside, then add ESIMAL — an infinitely tiny ending for a tiny thing."},"wo-infinitesimal":{src:"lore:infinitesimal:0",route:"#/word/infinitesimal",cta:"Open the word card",title:"Where it comes from · infinitesimal",body:"Latin infinitus = unbounded + -esimus = ordinal suffix"},"wd-diminutive":{src:"concept:106:words:2:def",route:"#/word/diminutive",cta:"Open the word card",title:"diminutive",roman:"dih-MIH-nyuh-tihv",body:"a word that is formed with a suffix (such as -let or -kin) to indicate smallness",clip:1},"wx-diminutive":{src:"concept:106:words:2:ex",route:"#/word/diminutive",cta:"Open the word card",title:"In a sentence · diminutive",body:"diminutive in stature",clip:1},"wh-diminutive":{src:"concept:106:words:2:hook",route:"#/word/diminutive",cta:"Open the word card",title:"Remember it · diminutive",body:"A diMINutive thing is so MINI it fits in a tiny suffix like -let or -kin."},"wo-diminutive":{src:"lore:diminutive:0",route:"#/word/diminutive",cta:"Open the word card",title:"Where it comes from · diminutive",body:"Latin diminutivus = tending to lessen"},"wd-microscopic":{src:"concept:106:words:3:def",route:"#/word/microscopic",cta:"Open the word card",title:"microscopic",roman:"meye-kruh-SKAH-pihk",body:"of or relating to or used in microscopy",clip:1},"wx-microscopic":{src:"concept:106:words:3:ex",route:"#/word/microscopic",cta:"Open the word card",title:"In a sentence · microscopic",body:"microscopic analysis",clip:1},"wh-microscopic":{src:"concept:106:words:3:hook",route:"#/word/microscopic",cta:"Open the word card",title:"Remember it · microscopic",body:"MICROSCOPIC ends in '-ic' like 'atomic'—no 'k', just micro+scop+ic."},"wx-colossal":{src:"concept:106:words:4:ex",route:"#/word/colossal",cta:"Open the word card",title:"In a sentence · colossal",body:"colossal crumbling ruins of an ancient temple",clip:1},"wh-colossal":{src:"concept:106:words:4:hook",route:"#/word/colossal",cta:"Open the word card",title:"Remember it · colossal",body:"The coLOSSal Colossus had one L but a LOSS of balance — one L, double S: coLOSSal."},"wo-colossal":{src:"lore:colossal:0",route:"#/word/colossal",cta:"Open the word card",title:"Where it comes from · colossal",body:"Greek kolossos = giant statue"},"wd-titanic":{src:"concept:106:words:5:def",route:"#/word/titanic",cta:"Open the word card",title:"titanic",roman:"teye-TA-nihk",body:"of great force or power",clip:1},"wx-titanic":{src:"concept:106:words:5:ex",route:"#/word/titanic",cta:"Open the word card",title:"In a sentence · titanic",body:"The titanic storm uprooted century-old trees and tore rooftops from houses across the county.",clip:1}});
